window.DQ=window.DQ||{};DQ["pesach"]={"a":[["אֵיזֶה מַאֲכָל הוּא חָמֵץ?",["תַּפּוּחַ","בֵּיצָה קָשָׁה","פִּתָּה"],2,"פִּתָּה עֲשׂוּיָה מִקֶּמַח חִטָּה וּמַיִם שֶׁהֶחְמִיצוּ – הִיא חָמֵץ. תַּפּוּחַ וּבֵיצָה אֵינָם מֵחֲמֵשֶׁת מִינֵי דָּגָן.","פֶּרֶק ב׳, הֲלָכָה ג׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["מֵאֵיזֶה צֶמַח יָכוֹל לְהִוָּצֵר חָמֵץ?",["שִׁבֳּלֵי חִטָּה","תַּפּוּחֵי אֲדָמָה","עֲנָבִים"],0,"חִטָּה הִיא אַחַת מֵחֲמֵשֶׁת מִינֵי דָּגָן. רַק מֵהֶם, כְּשֶׁהֵם נוֹגְעִים בְּמַיִם וּמַחְמִיצִים, נוֹצָר חָמֵץ.","פֶּרֶק ב׳, הֲלָכָה ג׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["בָּצֵק שֶׁל קֶמַח וּמַיִם עוֹמֵד עַל הַשֻּׁלְחָן, וְאַף אֶחָד לֹא לָשׁ אוֹתוֹ. אַחֲרֵי כַּמָּה זְמַן הוּא מַתְחִיל לְהַחְמִיץ?",["אַחֲרֵי יוֹם שָׁלֵם","אַחֲרֵי שְׁמוֹנֶה עֶשְׂרֵה דַּקּוֹת","אַחֲרֵי שָׁבוּעַ"],1,"בָּצֵק שֶׁעוֹמֵד 18 דַּקּוֹת בְּלִי לִישָׁה מַתְחִיל לְהַחְמִיץ, וּבְמָקוֹם חַם – עוֹד קֹדֶם. כָּל זְמַן שֶׁלָּשִׁים אוֹתוֹ, הוּא לֹא מַחְמִיץ.","פֶּרֶק ב׳, הֲלָכָה ד׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["אֵיזֶה בָּצֵק כְּבָר הֶחְמִיץ?",["בָּצֵק שֶׁלָּשִׁים אוֹתוֹ עַכְשָׁו","קֶמַח יָבֵשׁ בְּשַׂקִּית","בָּצֵק שֶׁנִּסְדַּק"],2,"סְדָקִים בַּבָּצֵק הֵם סִימָן שֶׁהֶחְמִיץ. בָּצֵק שֶׁלָּשִׁים אוֹתוֹ כָּל הַזְּמַן אֵינוֹ מַחְמִיץ, וְקֶמַח שֶׁלֹּא נָגַע בְּמַיִם אֵינוֹ מַחְמִיץ.","פֶּרֶק ב׳, הֲלָכוֹת ג׳–ד׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["עֶרֶב פֶּסַח בַּבֹּקֶר. עַד מָתַי מֻתָּר לֶאֱכֹל חָמֵץ?",["עַד חֲצוֹת הַיּוֹם","עַד סוֹף אַרְבַּע שָׁעוֹת","עַד הַשְּׁקִיעָה"],1,"בְּאַרְבַּע הַשָּׁעוֹת הָרִאשׁוֹנוֹת שֶׁל הַיּוֹם מֻתָּר לֶאֱכֹל חָמֵץ. אַחַר כָּךְ חֲכָמִים אָסְרוּ אֶת אֲכִילָתוֹ, כְּדֵי שֶׁלֹּא נִטְעֶה בַּזְּמַן.","פֶּרֶק ב׳, הֲלָכָה ב׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["בַּשָּׁעָה הַחֲמִישִׁית בְּעֶרֶב פֶּסַח נִשְׁאֲרָה פְּרוּסַת לֶחֶם. מָה מֻתָּר לַעֲשׂוֹת בָּהּ?",["לְהַאֲכִיל בָּהּ אֶת הַתַּרְנְגוֹלוֹת","לֶאֱכֹל אוֹתָהּ מַהֵר","לִשְׁמֹר אוֹתָהּ לְאַחַר הֶחָג"],0,"בַּשָּׁעָה הַחֲמִישִׁית אָסוּר לֶאֱכֹל חָמֵץ, אֲבָל עֲדַיִן מֻתָּר לֵהָנוֹת מִמֶּנּוּ – לְמָשָׁל לְהַאֲכִיל בּוֹ בְּהֵמָה. לִשְׁמֹר חָמֵץ לְאַחַר הֶחָג – אָסוּר.","פֶּרֶק ב׳, הֲלָכָה ב׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["בַּמַּחְסָן יֵשׁ שַׂק אֹכֶל לִכְלָבִים, וְיֵשׁ בּוֹ חִטָּה. מָה עוֹשִׂים לִפְנֵי פֶּסַח?",["מַשְׁאִירִים, כִּי זֶה רַק לִכְלָבִים","מְבַעֲרִים אוֹתוֹ","מַאֲכִילִים בּוֹ אֶת הַכֶּלֶב בְּפֶסַח"],1,"הֶחָמֵץ שֶׁבְּאֹכֶל לִכְלָבִים הָיָה רָאוּי מִתְּחִלָּתוֹ לְאָדָם, וְלָכֵן חוֹבָה לְבַעֵר אוֹתוֹ לִפְנֵי פֶּסַח.","פֶּרֶק ב׳, הֲלָכָה ו׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["מָה מְסַמֵּל הַבָּצֵק שֶׁתּוֹפֵחַ וּמִתְנַפֵּחַ?",["גַּאֲוָה","עֲנָוָה","שִׂמְחָה"],0,"הֶחָמֵץ מִתְנַפֵּחַ כְּמוֹ אָדָם גַּאַוְתָן שֶׁמַּגְדִּיל אֶת עַצְמוֹ. הַמַּצָּה הַדַּקָּה רוֹמֶזֶת לָעֲנָוָה.","פֶּרֶק א׳, הֲלָכָה ה׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["שָׁכֵן גּוֹי הִשְׁאִיר אֶצְלְכֶם אַרְגַּז עוּגִיּוֹת שֶׁלּוֹ, וְלֹא קִבַּלְתֶּם עָלָיו אַחְרָיוּת. מָה עוֹשִׂים בְּפֶסַח?",["שׂוֹרְפִים אֶת הָאַרְגָּז","אוֹכְלִים מִמֶּנּוּ קְצָת","נוֹעֲלִים אוֹתוֹ בָּאָרוֹן"],2,"חָמֵץ שֶׁל גּוֹי אֵינוֹ ״לְךָ״, וְלֹא צָרִיךְ לְבַעֵר אוֹתוֹ. אֲבָל נוֹעֲלִים אוֹתוֹ אוֹ עוֹשִׂים לְפָנָיו מְחִצָּה, כְּדֵי שֶׁלֹּא נִשְׁכַּח וְנֹאכַל מִמֶּנּוּ.","פֶּרֶק ג׳, הֲלָכָה ב׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["מָתַי מַתְחִילִים לִלְמֹד הִלְכוֹת פֶּסַח?",["בְּפוּרִים","בַּחֲנֻכָּה","בְּעֶרֶב פֶּסַח"],0,"לוֹמְדִים הִלְכוֹת פֶּסַח שְׁלוֹשִׁים יוֹם לִפְנֵי הֶחָג – מִפּוּרִים. הַהֲלָכוֹת רַבּוֹת, וְצָרִיךְ זְמַן לְהִתְכּוֹנֵן.","פֶּרֶק א׳, הֲלָכָה ח׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["מָתַי בּוֹדְקִים חָמֵץ?",["בְּלֵיל הַסֵּדֶר","בְּלֵיל י״ד בְּנִיסָן","בְּפוּרִים בַּבֹּקֶר"],1,"בּוֹדְקִים בִּתְחִלַּת לֵיל י״ד בְּנִיסָן, הַלַּיְלָה שֶׁלִּפְנֵי עֶרֶב פֶּסַח: כֻּלָּם בַּבַּיִת, וְאוֹר הַנֵּר בּוֹלֵט בַּחֹשֶׁךְ.","פֶּרֶק ד׳, הֲלָכָה א׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["אַבָּא בֵּרַךְ ״עַל בִּעוּר חָמֵץ״. מָה אָסוּר לוֹ לַעֲשׂוֹת לִפְנֵי שֶׁהוּא מַתְחִיל לִבְדֹּק?",["לְדַבֵּר בַּטֶּלֶפוֹן","לָלֶכֶת לַמִּטְבָּח","לְהָאִיר בַּנֵּר"],0,"בֵּין הַבְּרָכָה לַבְּדִיקָה אָסוּר לְדַבֵּר בְּעִנְיָנִים אֲחֵרִים. מִי שֶׁהִפְסִיק וְדִבֵּר – צָרִיךְ לְבָרֵךְ שׁוּב.","פֶּרֶק ד׳, הֲלָכָה ג׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["בְּמָה בּוֹדְקִים חָמֵץ?",["אֲבוּקָה עִם כַּמָּה פְּתִילוֹת","אוֹר הַשֶּׁמֶשׁ בַּצָּהֳרַיִם","נֵר שַׁעֲוָה אוֹ פַּנָּס"],2,"בּוֹדְקִים לְאוֹר נֵר שַׁעֲוָה, וּמֻתָּר גַּם בְּפַנָּס – לִשְׁנֵיהֶם אוֹר מְמֻקָּד. בַּאֲבוּקָה הַלֶּהָבָה גְּדוֹלָה וּמְסֻכֶּנֶת, וּבַיּוֹם אוֹר הַשֶּׁמֶשׁ מַחְלִישׁ אֶת אוֹר הַנֵּר.","פֶּרֶק ד׳, הֲלָכָה ה׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["אֵיפֹה צָרִיךְ לִבְדֹּק חָמֵץ?",["הַגִּנָּה הַצִּבּוּרִית","הַסַּפְסָל בַּתַּחֲנָה","הַמְּכוֹנִית וְהַתִּיק"],2,"בּוֹדְקִים כָּל מָקוֹם שֶׁלָּנוּ שֶׁנִּכְנָסִים אֵלָיו עִם חָמֵץ – גַּם אֶת הַמְּכוֹנִית וְאֶת הַתִּיקִים. מָקוֹם צִבּוּרִי שֶׁל הֶפְקֵר אֵינוֹ צָרִיךְ בְּדִיקָה.","פֶּרֶק ד׳, הֲלָכָה ד׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["בַּבַּיִת יֵשׁ יְלָדִים קְטַנִּים. אֵיזֶה מָקוֹם צָרִיךְ לִבְדֹּק?",["כִּיסֵי הַמְּעִיל שֶׁל הַקָּטָן","מַדָּף גָּבוֹהַּ שֶׁהוּא לֹא מַגִּיעַ","אַרְגַּז כְּלֵי עֲבוֹדָה נָעוּל"],0,"יְלָדִים קְטַנִּים שָׂמִים אֹכֶל בַּכִּיסִים וּמַחְבִּיאִים אוֹתוֹ, וְלָכֵן בּוֹדְקִים אֶת הַכִּיסִים שֶׁלָּהֶם וְאֶת כָּל מָקוֹם שֶׁהַיָּד שֶׁלָּהֶם מַגִּיעָה. מַדָּף גָּבוֹהַּ שֶׁהֵם לֹא מַגִּיעִים – לֹא צָרִיךְ.","פֶּרֶק ד׳, הֲלָכוֹת ד׳, ו׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["מָה כְּדַאי לַעֲשׂוֹת מִי שֶׁמַּחְבִּיא אֶת עֲשֶׂרֶת הַפְּתִיתִים?",["לְהַחְבִּיא אוֹתָם בְּתוֹךְ הַפַּח","לִרְשֹׁם אֵיפֹה הֶחְבִּיא אוֹתָם","לֶאֱכֹל אֶחָד מֵהֶם"],1,"רוֹשְׁמִים אֵיפֹה הֶחְבִּיאוּ, כְּדֵי שֶׁאִם הַבּוֹדֵק לֹא יִמְצָא פְּתִית – יוֹצִיאוּ אוֹתוֹ וִיבַעֲרוּ, וְהוּא לֹא יִשָּׁאֵר בַּבַּיִת בְּפֶסַח.","פֶּרֶק ד׳, הֲלָכָה ט׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["הַבַּיִת נֻקָּה הֵיטֵב לְפֶסַח. מָה עוֹשִׂים בְּלֵיל י״ד?",["לֹא בּוֹדְקִים בִּכְלָל","בּוֹדְקִים בִּבְרָכָה, בְּדִיקָה קַלָּה","מְנַקִּים שׁוּב אֶת כָּל הַבַּיִת"],1,"גַּם אַחֲרֵי נִקָּיוֹן יְסוֹדִי בּוֹדְקִים בִּבְרָכָה: עוֹבְרִים עַל כָּל הַבַּיִת, פּוֹתְחִים אֲרוֹנוֹת וּמְגֵרוֹת וּמִסְתַּכְּלִים בַּפִּנּוֹת. הַמִּנְהָג שֶׁבְּמָקוֹם שֶׁנֻּקָּה הֵיטֵב זוֹ בְּדִיקָה קַלָּה שֶׁל דַּקּוֹת סְפוּרוֹת, וְיֵשׁ מַחְמִירִים לִבְדֹּק גַּם אָז בְּכָל הַחוֹרִים וְהַסְּדָקִים.","פֶּרֶק ד׳, הֲלָכָה ח׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["אֵיפֹה צָרִיךְ לְנַקּוֹת עַד שֶׁלֹּא יִשָּׁאֵר אֲפִלּוּ פֵּרוּר?",["שֻׁלְחַן הָאֹכֶל וְהַשַּׁיִשׁ","בֵּין הַמַּרְצָפוֹת","בֵּין דַּפֵּי הַסְּפָרִים"],0,"מָה שֶׁנּוֹגֵעַ בְּאֹכֶל שֶׁל פֶּסַח צָרִיךְ לִהְיוֹת נָקִי מִכָּל פֵּרוּר – לְכָל הַדֵּעוֹת. בֵּין הַמַּרְצָפוֹת הַפֵּרוּרִים מְאוּסִים. אֶת דַּפֵּי הַסְּפָרִים – לְדַעַת כַּמָּה אַחֲרוֹנִים בּוֹדְקִים, אֲבָל הַמִּנְהָג לְהָקֵל.","פֶּרֶק ד׳, הֲלָכוֹת ו׳–ז׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["אֵיפֹה לֹא מַנִּיחִים בְּפֶסַח סֵפֶר שֶׁלָּמְדוּ בּוֹ כָּל הַשָּׁנָה?",["עַל מַדַּף הַסְּפָרִים","עַל שֻׁלְחַן הַלִּמּוּד","עַל שֻׁלְחַן הָאֹכֶל"],2,"מִסֵּפֶר כָּזֶה עָלוּל לִפֹּל פֵּרוּר חָמֵץ לְתוֹךְ הָאֹכֶל, וְחָמֵץ בְּפֶסַח אֵינוֹ בָּטֵל. לוֹמְדִים בּוֹ עַל שֻׁלְחָן אַחֵר.","פֶּרֶק ד׳, הֲלָכָה ז׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["מָה עוֹשִׂים בַּבֹּקֶר בֶּחָמֵץ שֶׁנִּמְצָא בַּבְּדִיקָה?",["שׂוֹרְפִים אוֹתוֹ","שׁוֹמְרִים אוֹתוֹ לְאַחַר הֶחָג","מַחְזִירִים אוֹתוֹ לָאָרוֹן"],0,"יִשְׂרָאֵל קְדוֹשִׁים נָהֲגוּ לְבַעֵר אֶת הֶחָמֵץ בִּשְׂרֵפָה – הַדֶּרֶךְ שֶׁמְּבַעֶרֶת אוֹתוֹ מִן הָעוֹלָם יוֹתֵר מִכֻּלָּן.","פֶּרֶק ה׳, הֲלָכָה ד׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["נִשְׁאֲרוּ אֵצֶל אַבָּא הַרְבֵּה אַרְגְּזֵי פַּסְטָה לִפְנֵי פֶּסַח. מָה יַעֲשֶׂה כְּדֵי לֹא לְהַפְסִיד?",["יִמְכֹּר אוֹתָם לְגוֹי דֶּרֶךְ הָרַב","יַחְבִּיא אוֹתָם בַּמַּחְסָן","יִתֵּן אוֹתָם לְשָׁכֵן יְהוּדִי"],0,"מְכִירַת חָמֵץ לְגוֹי מַצִּילָה אֶת הֶחָמֵץ מֵהֶפְסֵד. הַחְבָּאָה בַּמַּחְסָן לֹא מוֹעִילָה – הֶחָמֵץ עֲדַיִן שֶׁלּוֹ. וּשְׁכֵנוֹ הַיְּהוּדִי יַעֲבֹר עָלָיו בְּ״בַל יֵרָאֶה״.","פֶּרֶק ו׳, הֲלָכוֹת א׳, ג׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["אֵיךְ שׁוֹמְרִים בְּפֶסַח עַל הֶחָמֵץ שֶׁנִּמְכַּר?",["מַשְׁאִירִים אוֹתוֹ עַל הַשַּׁיִשׁ","סוֹגְרִים בָּאָרוֹן עִם נְיַר דֶּבֶק","מַעֲבִירִים אוֹתוֹ לַמְּקָרֵר"],1,"הֶחָמֵץ שֶׁל הַגּוֹי נִשְׁאָר בַּבַּיִת, וְלָכֵן סוֹגְרִים אוֹתוֹ בָּאָרוֹן וּמַדְבִּיקִים נְיַר דֶּבֶק – כְּדֵי שֶׁלֹּא נִפְתַּח וְנֹאכַל מִמֶּנּוּ בְּטָעוּת.","פֶּרֶק ו׳, הֲלָכָה ג׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["אֵיזוֹ חֲבִילַת עוּגִיּוֹת מֻתָּר לִקְנוֹת לְפֶסַח?",["חֲבִילָה בְּלִי שׁוּם חוֹתֶמֶת","חֲבִילָה שֶׁנִּפְתְּחָה אֶתְמוֹל","חֲבִילָה עִם חוֹתֶמֶת כָּשֵׁר לְפֶסַח"],2,"מַאֲכָל מִבֵּית חֲרֹשֶׁת אוֹכְלִים בְּפֶסַח רַק עִם חוֹתֶמֶת כַּשְׁרוּת לְפֶסַח, כִּי אוּלַי אֶחָד מֵהַחֳמָרִים שֶׁבּוֹ אֵינוֹ כָּשֵׁר לְפֶסַח.","פֶּרֶק ח׳, הֲלָכָה ד׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["יוֹסִי חוֹלֶה בְּפֶסַח. אֵיזוֹ תְּרוּפָה צְרִיכָה כַּשְׁרוּת לְפֶסַח?",["גְּלוּלָה מָרָה לִבְלִיעָה","סִירוֹפּ מָתוֹק","מִשְׁחָה לָעוֹר"],1,"סִירוֹפּ מָתוֹק רָאוּי לַאֲכִילָה, וְלָכֵן צָרִיךְ לְבָרֵר שֶׁהוּא כָּשֵׁר לְפֶסַח. גְּלוּלָה מָרָה – נִפְסְלָה מֵאֲכִילַת כֶּלֶב, וּמִשְׁחָה שֶׁנִּסְפֶּגֶת בָּעוֹר אֵינָהּ צְרִיכָה כַּשְׁרוּת.","פֶּרֶק ח׳, הֲלָכוֹת ז׳, ט׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["אֵיזֶה מוּצָר צָרִיךְ כַּשְׁרוּת לְפֶסַח?",["מִשְׁחַת נַעֲלַיִם","מִשְׁחַת שִׁנַּיִם","סַבּוֹן כֵּלִים"],1,"לְמִשְׁחַת שִׁנַּיִם יֵשׁ טַעַם, וְהִיא כְּמוֹ מוּצַר מָזוֹן. מִשְׁחַת נַעֲלַיִם וְסַבּוֹן כֵּלִים אֵינָם צְרִיכִים שׁוּם הַשְׁגָּחָה.","פֶּרֶק ח׳, הֲלָכָה ט׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["אֵיזֶה מוּצָר אֵינוֹ צָרִיךְ שׁוּם הַשְׁגָּחָה לְפֶסַח?",["כּוֹסוֹת נְיָר","מִשְׁחַת שִׁנַּיִם","סִירוֹפּ לְשִׁעוּל"],0,"בְּכוֹסוֹת נְיָר, נְיַר כֶּסֶף וּנְיַר אֲפִיָּה אֵין טַעַם מֻרְגָּשׁ, וְאֵין לַחְשֹׁשׁ לָהֶם. מִשְׁחַת שִׁנַּיִם וְסִירוֹפּ – יֵשׁ לָהֶם טַעַם, וְהֵם צְרִיכִים כַּשְׁרוּת.","פֶּרֶק ח׳, הֲלָכוֹת ז׳, ט׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["אֵיזֶה מֵאֵלֶּה הוּא קִטְנִיּוֹת?",["תַּפּוּחַ אֲדָמָה","תִּירָס","גֶּזֶר"],1,"תִּירָס הוּא מִמִּינֵי הַקִּטְנִיּוֹת, וְגַם קוֹרְנְפְלֶקְס שֶׁעָשׂוּי מִמֶּנּוּ. תַּפּוּחֵי אֲדָמָה וְגֶזֶר – יְרָקוֹת, וְאֵינָם קִטְנִיּוֹת.","פֶּרֶק ט׳, הֲלָכָה ד׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["מָה אֵינוֹ כָּלוּל בְּמִנְהַג הַקִּטְנִיּוֹת?",["קֶמַח תַּפּוּחֵי אֲדָמָה","קוֹרְנְפְלֶקְס","פְּרִיכִיּוֹת אֹרֶז"],0,"תַּפּוּחֵי אֲדָמָה לֹא הָיוּ בְּאֵירוֹפָּה כְּשֶׁהִתְחִיל הַמִּנְהָג, וְלָכֵן הֵם אֵינָם בִּכְלָלוֹ. קוֹרְנְפְלֶקְס עָשׂוּי מִתִּירָס, וּפְרִיכִיּוֹת מֵאֹרֶז – וְהֵם כְּלוּלִים בַּמִּנְהָג.","פֶּרֶק ט׳, הֲלָכָה ד׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["מִשְׁפָּחָה שֶׁלֹּא אוֹכֶלֶת קִטְנִיּוֹת, וְיֵשׁ לָהּ שַׂק תִּירָס. מָה מֻתָּר לָהֶם בְּפֶסַח?",["לְהַאֲכִיל בּוֹ אֶת הַתַּרְנְגוֹלוֹת","לְהָכִין מִמֶּנּוּ פּוֹפְּקוֹרְן","חַיָּבִים לִשְׂרֹף אוֹתוֹ"],0,"קִטְנִיּוֹת אֵינָן חָמֵץ: מֻתָּר לְהַשְׁאִיר אוֹתָן בַּבַּיִת וְלֵהָנוֹת מֵהֶן – לְמָשָׁל לְהַאֲכִיל בָּהֶן בַּעֲלֵי חַיִּים. רַק לֶאֱכֹל אוֹתָן הֵם נוֹהֲגִים שֶׁלֹּא.","פֶּרֶק ט׳, הֲלָכָה ה׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["תִּינוֹק בְּמִשְׁפָּחָה שֶׁלֹּא אוֹכֶלֶת קִטְנִיּוֹת צָרִיךְ דַּיְסַת אֹרֶז. מָה הַדִּין?",["אָסוּר עַד סוֹף הֶחָג","רַק אִם הוּא בְּסַכָּנָה","מֻתָּר לְהַאֲכִיל אוֹתוֹ"],2,"מֻתָּר לְהַאֲכִיל תִּינוֹקוֹת שֶׁצְּרִיכִים קִטְנִיּוֹת, וְגַם חוֹלֶה שֶׁאֵינוֹ בְּסַכָּנָה. בּוֹרְרִים הֵיטֵב אֶת הָאֹרֶז, וְרָאוּי לְהַקְצוֹת לוֹ כֵּלִים מְיֻחָדִים.","פֶּרֶק ט׳, הֲלָכָה ז׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["בְּאֵיזוֹ מַצָּה אֵין יוֹצְאִים יְדֵי חוֹבָה בְּלֵיל הַסֵּדֶר?",["מַצַּת מְכוֹנָה שְׁמוּרָה","מַצָּה שֶׁנֶּאֶפְתָה בַּשֶּׁמֶשׁ","מַצַּת יָד שְׁמוּרָה"],1,"מַצָּה שֶׁנֶּאֶפְתָה בְּחֹם הַשֶּׁמֶשׁ אֵינָהּ נִקְרֵאת ״לֶחֶם״, וְאֵין יוֹצְאִים בָּהּ. בְּמַצַּת מְכוֹנָה וּבְמַצַּת יָד שְׁמוּרוֹת – יוֹצְאִים, וְרַבִּים מְהַדְּרִים בְּמַצַּת יָד.","פֶּרֶק י״ב, הֲלָכוֹת ד׳, ח׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["בְּאֵילּוּ מַיִם לָשִׁים אֶת הַמַּצּוֹת?",["מַיִם חַמִּים מֵהַקֻּמְקוּם","מַיִם שֶׁעָמְדוּ בַּשֶּׁמֶשׁ","מַיִם שֶׁלָּנוּ לַיְלָה בְּמָקוֹם קָרִיר"],2,"״מַיִם שֶׁלָּנוּ״ שׁוֹאֲבִים מִבְּעוֹד יוֹם וּמַשְׁאִירִים כָּל הַלַּיְלָה בְּמָקוֹם קָרִיר. מַיִם חַמִּים אוֹ פּוֹשְׁרִים מְזָרְזִים אֶת הַחִמּוּץ.","פֶּרֶק י״ב, הֲלָכָה ו׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["מָה אָסוּר לְהוֹסִיף לַבָּצֵק שֶׁל הַמַּצּוֹת?",["מֶלַח וּפִלְפֵּל","קֶמַח","מַיִם צוֹנְנִים"],0,"לֹא נוֹתְנִים בָּעִסָּה מֶלַח אוֹ פִּלְפֵּל, כִּי הֵם עֲלוּלִים לְחַמֵּם אוֹתָהּ וּלְזָרֵז אֶת הַחִמּוּץ. הַמַּצָּה עֲשׂוּיָה מִקֶּמַח וּמַיִם צוֹנְנִים בִּלְבַד.","פֶּרֶק י״ב, הֲלָכָה ז׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["בַּמַּאֲפִיָּה: מָה עוֹשֶׂה הַלָּשׁ כְּשֶׁיָּדָיו מִתְחַמְּמוֹת?",["מַנִּיחַ אֶת הָעִסָּה וְהוֹלֵךְ לָנוּחַ","מְצַנֵּן אֶת יָדָיו בְּמַיִם קָרִים","מַמְשִׁיךְ לָלוּשׁ לְיַד הַתַּנּוּר"],1,"לֹא מַשְׁאִירִים אֶת הָעִסָּה בְּלִי עֵסֶק אֲפִלּוּ רֶגַע, וְלֹא לָשִׁים בְּמָקוֹם חַם. כְּשֶׁהַיָּדַיִם מִתְחַמְּמוֹת – מְצַנְּנִים אוֹתָן בְּמַיִם קָרִים.","פֶּרֶק י״ב, הֲלָכָה ז׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["אֵיזוֹ מַצָּה כְּשֵׁרָה לְפֶסַח?",["מַצָּה עִם צִיּוּרִים וְקִשּׁוּטִים","מַצָּה עָבָה טֶפַח, כְּמוֹ כִּכָּר","מַצָּה דַּקָּה וְקָשָׁה"],2,"לֹא מְצַיְּרִים עַל הַמַּצָּה, שֶׁמָּא תַּחְמִיץ בִּזְמַן הַצִּיּוּר. וּמַצָּה עָבָה טֶפַח – הָאֵשׁ לֹא שׁוֹלֶטֶת בְּתוֹכָהּ. הָאַשְׁכְּנַזִּים עוֹשִׂים מַצּוֹת דַּקּוֹת, וּבַסְּפָרַדִּים יֵשׁ שֶׁעוֹשִׂים מַצָּה בְּעֹבִי אֶצְבַּע – גַּם הִיא כְּשֵׁרָה.","פֶּרֶק י״ב, הֲלָכָה ח׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["עֶרֶב פֶּסַח, אַחֲרֵי חֲצוֹת הַיּוֹם. מָה מֻתָּר לַעֲשׂוֹת?",["לְהִסְתַּפֵּר אֵצֶל הַסַּפָּר","לְצַחְצֵחַ נַעֲלַיִם לִכְבוֹד הַחַג","לִתְפֹּר חֲלִיפָה חֲדָשָׁה"],1,"מֵחֲצוֹת אָסוּר לַעֲשׂוֹת מְלָאכָה חֲשׁוּבָה כְּמוֹ תִּסְפֹּרֶת וּתְפִירַת בְּגָדִים. צִחְצוּחַ נַעֲלַיִם, גִּהוּץ וּגְזִיזַת צִפָּרְנַיִם – מֻתָּרִים לִכְבוֹד הַחַג.","פֶּרֶק י״ג, הֲלָכָה ב׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["אֵיךְ נִפְטָרִים רֹב הַבְּכוֹרִים מִתַּעֲנִית בְּכוֹרוֹת?",["בָּאִים לְסִיּוּם מַסֶּכֶת וְאוֹכְלִים","יְשֵׁנִים עַד הַצָּהֳרַיִם","אוֹכְלִים מַצָּה בַּבֹּקֶר"],0,"אַחֲרֵי שַׁחֲרִית עוֹרְכִים סִיּוּם מַסֶּכֶת, וְהַכִּבּוּד שֶׁאַחֲרָיו הוּא סְעוּדַת מִצְוָה – וּמִי שֶׁאוֹכֵל בָּהּ נִפְטָר מֵהַצּוֹם. מַצָּה אָסוּר לֶאֱכֹל בְּעֶרֶב פֶּסַח.","פֶּרֶק י״ג, הֲלָכוֹת ה׳–ו׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["לְאַבָּא שֶׁאֵינוֹ בְּכוֹר נוֹלַד בֵּן בְּכוֹר, וְהַבֵּן עוֹד תִּינוֹק. מִי נוֹהֵג לָצוּם?",["הַתִּינוֹק צָם","אַף אֶחָד לֹא צָם","אַבָּא צָם בִּמְקוֹמוֹ"],2,"נָהֲגוּ שֶׁהָאָב צָם בִּמְקוֹם בְּנוֹ הַבְּכוֹר עַד שֶׁיִּגְדַּל. וְאִם גַּם הָאָב בְּכוֹר – הַצּוֹם שֶׁלּוֹ עוֹלֶה גַּם בִּשְׁבִיל בְּנוֹ.","פֶּרֶק י״ג, הֲלָכָה ד׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["דָּנִי בֶּן שֶׁבַע מֵבִין שֶׁהַמַּצָּה זֵכֶר לִיצִיאַת מִצְרַיִם. מָה יֹאכַל בְּעֶרֶב פֶּסַח בַּצָּהֳרַיִם?",["מַצָּה שְׁמוּרָה","קְצִיצוֹת מַצָּה מְבֻשָּׁלוֹת","פְּרוּסַת לֶחֶם"],1,"מַצָּה אֲסוּרָה בְּעֶרֶב פֶּסַח גַּם לִילָדִים שֶׁמְּבִינִים, וְחָמֵץ אָסוּר כְּבָר מִסּוֹף הַשָּׁעָה הָרְבִיעִית. קְצִיצוֹת מְבֻשָּׁלוֹת מִקֶּמַח מַצָּה מֻתָּרוֹת לְכָל הַדֵּעוֹת.","פֶּרֶק י״ג, הֲלָכוֹת ו׳–ז׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["יוֹסִי קָנָה מַצּוֹת, וְהַמּוֹכֵר בִּקֵּשׁ לְקַבֵּל אֶת הַכֶּסֶף מִיָּד. מָה יַעֲשֶׂה?",["יְשַׁלֵּם מִיָּד","יֹאמַר: ״לֵךְ וְשׁוּב״","יְשַׁלֵּם אַחֲרֵי הַחַג"],0,"אֵין יוֹצְאִים בְּמַצָּה גְּזוּלָה. מִי שֶׁדּוֹחֶה אֶת הַמּוֹכֵר שֶׁרוֹצֶה אֶת כַּסְפּוֹ – הַמַּצּוֹת אֵינָן שֶׁלּוֹ, וְלֹא יֵצֵא בָּהֶן יְדֵי חוֹבָה.","פֶּרֶק י״ב, הֲלָכָה ח׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["מָה אֵין מַנִּיחִים בִּקְעָרַת הַסֵּדֶר?",["חֲרֹסֶת","כּוֹס יַיִן","בֵּיצָה"],1,"בַּקְּעָרָה מַנִּיחִים מַאַכְלֵי מִצְוָה: מַצּוֹת, מָרוֹר, זְרוֹעַ, בֵּיצָה, כַּרְפַּס וַחֲרֹסֶת. הַיַּיִן אֵינוֹ בַּקְּעָרָה, כִּי הוּא מַשְׁקֶה וְלֹא מַאֲכָל.","פֶּרֶק ט״ז, הֲלָכָה ג׳","וְהִגַּדְתָּ לְבִנְךָ"],["בַּסֵּדֶר יוֹשְׁבִים רַק מְבֻגָּרִים, בְּלִי יְלָדִים. מִי שׁוֹאֵל ״מַה נִּשְׁתַּנָּה״?",["הַסַּבָּא הַמְּבֻגָּר","אַף אֶחָד לֹא שׁוֹאֵל","הַצָּעִיר שֶׁבַּמְּסֻבִּים"],2,"כְּשֶׁאֵין יְלָדִים – הַצָּעִיר שֶׁבַּמְּסֻבִּים שׁוֹאֵל. וְגַם מִי שֶׁעוֹשֶׂה אֶת הַסֵּדֶר לְבַד פּוֹתֵחַ בִּשְׁאֵלָה, כִּי כָּךְ הַסִּפּוּר שָׁלֵם יוֹתֵר.","פֶּרֶק ט״ו, הֲלָכָה ד׳","וְהִגַּדְתָּ לְבִנְךָ"],["מָה מְחַלְּקִים לַיְּלָדִים בִּתְחִלַּת הַסֵּדֶר, כְּדֵי שֶׁיִּשְׁאֲלוּ?",["פְּרוּסוֹת מַצָּה","אֱגוֹזִים וּמִינֵי מְתִיקָה","צַלַּחַת מָרָק"],1,"חֲכָמִים אָמְרוּ לְחַלֵּק לַקְּטַנִּים אֱגוֹזִים וּמִינֵי מְתִיקָה, כְּדֵי שֶׁיִּרְאוּ שִׁנּוּי וְיִשְׁאֲלוּ. וְטוֹב לְחַלֵּק לָהֶם מַמְתַּקִּים קְטַנִּים גַּם בְּמֶשֶׁךְ הַהַגָּדָה, כְּדֵי שֶׁיִּשָּׁאֲרוּ עֵרִים.","פֶּרֶק ט״ז, הֲלָכָה ב׳","וְהִגַּדְתָּ לְבִנְךָ"],["מָה מַנִּיחִים בַּקְּעָרָה זֵכֶר לְקָרְבַּן חֲגִיגָה?",["בֵּיצָה","תַּפּוּחַ","גֶּזֶר"],0,"הַבֵּיצָה הִיא זֵכֶר לְקָרְבַּן חֲגִיגָה, וְהַזְּרוֹעַ – זֵכֶר לְקָרְבַּן פֶּסַח. מַגִּישִׁים בֵּיצָה לְאָבֵל כְּדֵי לְנַחֵם, וְאַף אָנוּ מִתְנַחֲמִים שֶׁבְּקָרוֹב יִבָּנֶה הַמִּקְדָּשׁ.","פֶּרֶק ט״ז, הֲלָכָה ג׳","וְהִגַּדְתָּ לְבִנְךָ"],["בְּמָה טוֹבְלִים אֶת הַכַּרְפַּס?",["בַּחֲרֹסֶת","בִּדְבַשׁ","בְּמֵי מֶלַח אוֹ חֹמֶץ"],2,"אֶת הַכַּרְפַּס טוֹבְלִים בְּמֵי מֶלַח אוֹ חֹמֶץ, וּמְבָרְכִים ״בּוֹרֵא פְּרִי הָאֲדָמָה״. בַּחֲרֹסֶת טוֹבְלִים אֶת הַמָּרוֹר, מְאֻחָר יוֹתֵר.","פֶּרֶק ט״ז, הֲלָכָה ט״ו","וְהִגַּדְתָּ לְבִנְךָ"],["בְּ״יַחַץ״ – אֵיזוֹ מַצָּה בּוֹצְעִים לִשְׁנַיִם?",["הָעֶלְיוֹנָה","הַתַּחְתּוֹנָה","הָאֶמְצָעִית"],2,"בּוֹצְעִים אֶת הַמַּצָּה הָאֶמְצָעִית. הָעֶלְיוֹנָה וְהַתַּחְתּוֹנָה נִשְׁאָרוֹת שְׁלֵמוֹת, כְּדֵי שֶׁיִּהְיֶה ״לֶחֶם מִשְׁנֶה״ לְבִרְכַּת ״הַמּוֹצִיא״.","פֶּרֶק ט״ז, הֲלָכָה ט״ז","וְהִגַּדְתָּ לְבִנְךָ"],["מָה עוֹשִׂים עִם הַחֵלֶק הַגָּדוֹל שֶׁל הַמַּצָּה הָאֶמְצָעִית?",["עוֹטְפִים בְּמַפִּית וְשׁוֹמְרִים לָאֲפִיקוֹמָן","אוֹכְלִים אוֹתוֹ מִיָּד","מַחְזִירִים אוֹתוֹ לָאָרוֹן"],0,"אֶת הַחֵלֶק הַגָּדוֹל עוֹטְפִים בְּמַפִּית וּמַחְבִּיאִים, וְאוֹכְלִים אוֹתוֹ בְּסוֹף הַסְּעוּדָה – זֵכֶר לְקָרְבַּן הַפֶּסַח.","פֶּרֶק ט״ז, הֲלָכָה ט״ז","וְהִגַּדְתָּ לְבִנְךָ"],["אַחֲרֵי ״הָא לַחְמָא עַנְיָא״ מְסִירִים אֶת הַקְּעָרָה מֵהַשֻּׁלְחָן. לָמָּה?",["כְּדֵי לְפַנּוֹת מָקוֹם לָאֹכֶל","כְּדֵי שֶׁהַיְּלָדִים יִתְמְהוּ וְיִשְׁאֲלוּ","כִּי הַסֵּדֶר נִגְמַר"],1,"מְסִירִים אֶת הַקְּעָרָה כְּאִלּוּ הַסֵּדֶר נִגְמַר, וְהַיְּלָדִים שׁוֹאֲלִים: עוֹד לֹא אָכַלְנוּ! אַחַר כָּךְ מַחְזִירִים אוֹתָהּ, כְּדֵי לוֹמַר אֶת הַהַגָּדָה כְּשֶׁהַמַּצּוֹת וְהַמָּרוֹר לְפָנֵינוּ.","פֶּרֶק ט״ז, הֲלָכָה י״ז","וְהִגַּדְתָּ לְבִנְךָ"],["בַּאֲמִירַת עֶשֶׂר הַמַּכּוֹת – מָה עוֹשִׂים עִם הַכּוֹס?",["מַטִּיפִים מִמֶּנָּה מְעַט יַיִן","שׁוֹתִים מִמֶּנָּה לְגִימָה","מְכַסִּים אוֹתָהּ בְּמַפִּית"],0,"נָהֲגוּ לְהַטִּיף מְעַט יַיִן בְּ״דָם וָאֵשׁ וְתִימְרוֹת עָשָׁן״, בְּעֶשֶׂר הַמַּכּוֹת וּבְ״דְצַ״ךְ עֲדַ״שׁ בְּאַחַ״ב״ – שֵׁשׁ עֶשְׂרֵה פְּעָמִים. אֶת הַכּוֹס הַשְּׁנִיָּה שׁוֹתִים רַק בְּסוֹף ״מַגִּיד״.","פֶּרֶק ט״ז, הֲלָכָה י״ט","וְהִגַּדְתָּ לְבִנְךָ"],["אֵיתָן בֶּן שֵׁשׁ, וְהוּא מֵבִין אֶת הַקִּדּוּשׁ וְהַהַגָּדָה. כַּמָּה כּוֹסוֹת נוֹתְנִים לוֹ?",["כּוֹס אַחַת לַקִּדּוּשׁ","בְּלִי כּוֹסוֹת בִּכְלָל","אַרְבַּע כּוֹסוֹת"],2,"קְטַנִּים שֶׁהִגִּיעוּ לְגִיל חִנּוּךְ מְקַבְּלִים אַרְבַּע כּוֹסוֹת. מַסְפִּיק שֶׁיִּשְׁתּוּ ״מְלֹא לֻגְמָיו״ – כַּמָּה שֶׁמְּמַלֵּא אֶת הַפֶּה.","פֶּרֶק ט״ז, הֲלָכָה ט׳","וְהִגַּדְתָּ לְבִנְךָ"],["לְאֵיזֶה צַד מְסִבִּים בְּלֵיל הַסֵּדֶר?",["לְצַד יָמִין","לְצַד שְׂמֹאל","יוֹשְׁבִים זָקוּף"],1,"מַטִּים לְצַד שְׂמֹאל, וְהַיָּד הַיְּמָנִית נִשְׁאֶרֶת פְּנוּיָה לַמַּצָּה וְלַכּוֹס. מִי שֶׁמֵּסֵב לְיָמִין עָלוּל לְהֵחָנֵק – וְלָכֵן גַּם שְׂמָאלִי מֵסֵב לְשְׂמֹאל.","פֶּרֶק ט״ז, הֲלָכָה י״א","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["בְּאֵיזֶה שָׁלָב בַּסֵּדֶר לֹא מְסִבִּים?",["אֲכִילַת הַמַּצָּה","שְׁתִיַּת הַכּוֹס","אֲכִילַת הַמָּרוֹר"],2,"הַמָּרוֹר זֵכֶר לַשִּׁעְבּוּד, וְאֵין צֹרֶךְ לְהָסֵב בּוֹ. בַּמַּצָּה וּבְאַרְבַּע הַכּוֹסוֹת – חוֹבָה לְהָסֵב.","פֶּרֶק ט״ז, הֲלָכָה י׳","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["אֵיזֶה יָרָק הוּא הַמְּהֻדָּר בְּיוֹתֵר לְמָרוֹר?",["חַסָּה","גֶּזֶר","מְלָפְפוֹן"],0,"חֲכָמִים אָמְרוּ שֶׁהַמְּהֻדָּר בְּיוֹתֵר הוּא חַסָּה, וּשְׁמָהּ רוֹמֵז שֶׁה׳ חָס עָלֵינוּ. אֶפְשָׁר גַּם בַּחֲזֶרֶת (חֲרֵיין).","פֶּרֶק ט״ז, הֲלָכָה כ״ז","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["אֵיךְ אוֹכְלִים אֶת הַמָּרוֹר?",["טוֹבְלִים בְּמֵי מֶלַח","טוֹבְלִים בַּחֲרֹסֶת וּמְנַעֲרִים","בְּלִי לִטְבֹּל בִּכְלָל"],1,"טוֹבְלִים אֶת הַמָּרוֹר בַּחֲרֹסֶת – זֵכֶר לַטִּיט – וּמְנַעֲרִים, כְּדֵי שֶׁלֹּא יִתְבַּטֵּל טַעַם הַמָּרוֹר. בְּמֵי מֶלַח טוֹבְלִים אֶת הַכַּרְפַּס.","פֶּרֶק ט״ז, הֲלָכָה כ״ז","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["מָה עוֹשִׂים עִם הַחַסָּה בְּעֶרֶב פֶּסַח?",["מְבַשְּׁלִים אוֹתָהּ בְּמָרָק","מַשְׁאִירִים אוֹתָהּ בַּשֶּׁמֶשׁ","בּוֹדְקִים שֶׁאֵין בָּהּ תּוֹלָעִים"],2,"בַּחַסָּה מְצוּיוֹת תּוֹלָעִים, וְלָכֵן מְנַקִּים וּבוֹדְקִים אוֹתָהּ הֵיטֵב בְּעֶרֶב פֶּסַח. טוֹב לִקְנוֹת חַסָּה שֶׁגָּדְלָה בְּלִי תּוֹלָעִים.","פֶּרֶק ט״ז, הֲלָכָה כ״ז","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["מָה כּוֹרְכִים בְּ״כוֹרֵךְ״?",["מָרוֹר בְּתוֹךְ מַצָּה","בֵּיצָה בְּתוֹךְ מַצָּה","כַּרְפַּס בְּתוֹךְ חַסָּה"],0,"כּוֹרְכִים כְּזַיִת מָרוֹר בְּתוֹךְ כְּזַיִת מַצָּה, טוֹבְלִים בַּחֲרֹסֶת וְאוֹכְלִים בַּהֲסִבָּה – ״זֵכֶר לַמִּקְדָּשׁ כְּהִלֵּל״.","פֶּרֶק ט״ז, הֲלָכָה כ״ח","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["אֵיזֶה מַאֲכָל רֹב הַקְּהִלּוֹת לֹא אוֹכְלוֹת בְּלֵיל הַסֵּדֶר?",["עוֹף מְבֻשָּׁל בְּסִיר","בָּשָׂר צָלוּי עַל הָאֵשׁ","בֵּיצָה מְבֻשֶּׁלֶת"],1,"עוֹלֵי אַשְׁכְּנַז וְרֹב עוֹלֵי סְפָרַד לֹא אוֹכְלִים בְּלֵיל פֶּסַח בָּשָׂר צָלוּי, שֶׁלֹּא יֵרָאֶה כְּקָרְבַּן פֶּסַח מִחוּץ לִירוּשָׁלַיִם. עוֹלֵי תֵּימָן נוֹהֲגִים לֶאֱכֹל צָלִי – וְכָל קְהִלָּה כְּמִנְהָגָהּ.","פֶּרֶק ט״ז, הֲלָכָה ל״ב","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["מַה מֻּתָּר לִשְׁתּוֹת וְלֶאֱכֹל אַחֲרֵי אֲכִילַת הָאֲפִיקוֹמָן?",["מַיִם","עוּגָה","פֵּרוֹת"],0,"אַחֲרֵי הָאֲפִיקוֹמָן לֹא אוֹכְלִים כְּלוּם, כְּדֵי שֶׁטַּעַם הַמַּצָּה יִשָּׁאֵר בַּפֶּה. מַיִם מֻתָּרִים, כִּי אֵין לָהֶם טַעַם.","פֶּרֶק ט״ז, הֲלָכָה ל״ג","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["לִפְנֵי בִּרְכַּת ״עַל אֲכִילַת מַצָּה״ מַשְׁמִיטִים מַצָּה אַחַת מֵהַיָּד. אֵיזוֹ?",["הָעֶלְיוֹנָה","הָאֶמְצָעִית","הַתַּחְתּוֹנָה"],2,"מְבָרְכִים ״הַמּוֹצִיא״ עַל שָׁלֹשׁ הַמַּצּוֹת, וְאָז מַשְׁמִיטִים אֶת הַתַּחְתּוֹנָה. אֶת ״עַל אֲכִילַת מַצָּה״ מְבָרְכִים עַל הָעֶלְיוֹנָה וְעַל הָאֶמְצָעִית הַחֲצוּיָה – ״לֶחֶם עֹנִי״.","פֶּרֶק ט״ז, הֲלָכָה כ״ו","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["בְּ״שְׁפֹךְ חֲמָתְךָ״ – מָה נוֹהֲגִים לַעֲשׂוֹת?",["סוֹגְרִים אֶת הַחַלּוֹנוֹת","מְכַבִּים אֶת הָאוֹרוֹת","פּוֹתְחִים אֶת הַדֶּלֶת"],2,"פּוֹתְחִים אֶת הַדֶּלֶת לְהַרְאוֹת שֶׁהַלַּיְלָה הַזֶּה מְשֻׁמָּר, וְאֵינֶנּוּ מְפַחֲדִים מִשּׂוֹנְאֵינוּ. בִּזְכוּת הָאֱמוּנָה הַזֹּאת יָבוֹא הַמָּשִׁיחַ. אַחֲרֵי ״שְׁפֹךְ חֲמָתְךָ״ סוֹגְרִים אֶת הַדֶּלֶת.","פֶּרֶק ט״ז, הֲלָכָה ל״ה","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"]],"b":[["לֶחָג יֵשׁ שְׁנֵי שֵׁמוֹת: ״חַג הַמַּצּוֹת״ וְ״חַג הַפֶּסַח״. כְּנֶגֶד מָה הֵם?",["הַמַּצּוֹת כְּנֶגֶד הָאֱמוּנָה, וְהַפֶּסַח כְּנֶגֶד סְגֻלַּת יִשְׂרָאֵל","הַמַּצּוֹת כְּנֶגֶד הַחֵרוּת, וְהַפֶּסַח כְּנֶגֶד קָרְבַּן הַתּוֹדָה","שְׁנֵיהֶם כְּנֶגֶד הַמַּכּוֹת, שֶׁפָּגְעוּ רַק בַּמִּצְרִים","הַמַּצּוֹת כְּנֶגֶד הַלֶּחֶם שֶׁבַּמִּדְבָּר, וְהַפֶּסַח כְּנֶגֶד הַמָּן"],0,"חַג הַמַּצּוֹת – ה׳ נִגְלָה וְגָאַל אוֹתָנוּ, וְזוֹ הָאֱמוּנָה. חַג הַפֶּסַח – ה׳ פָּסַח עַל בָּתֵּי יִשְׂרָאֵל, וְזוֹ סְגֻלַּת יִשְׂרָאֵל. וּשְׁנֵיהֶם יַחַד: שֵׁם ה׳ מִתְגַּלֶּה עַל יְדֵי יִשְׂרָאֵל.","פֶּרֶק א׳, הֲלָכָה א׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["בַּמָּה הָיְתָה יְצִיאַת מִצְרַיִם שׁוֹנָה מִנִּצְחוֹנוֹת שֶׁל עַמִּים אֲחֵרִים?",["יִשְׂרָאֵל הָפְכוּ אֶת הַמִּצְרִים לַעֲבָדִים, אֲבָל הֵיטִיבוּ אִתָּם","יִשְׂרָאֵל נִשְׁאֲרוּ בְּמִצְרַיִם וְשָׁלְטוּ בָּהּ בְּמִשְׁפָּט צֶדֶק","יִשְׂרָאֵל לֹא שִׁעְבְּדוּ אֶת הַמִּצְרִים, אֶלָּא רַק יָצְאוּ לְחֵרוּת","יִשְׂרָאֵל נִלְחֲמוּ בַּמִּצְרִים בְּעַצְמָם, בְּלִי עֶזְרָה מִן הַשָּׁמַיִם"],2,"כָּל הָעַמִּים, כְּשֶׁגָּבְרוּ עַל מִי שֶׁשִּׁעְבֵּד אוֹתָם, שִׁעְבְּדוּ אוֹתוֹ. יִשְׂרָאֵל רַק יָצְאוּ לְחֵרוּת – וְכָךְ הִתְגַּלָּה לָרִאשׁוֹנָה בָּעוֹלָם רַעְיוֹן הַחֵרוּת.","פֶּרֶק א׳, הֲלָכָה ב׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["לָמָּה בָּנוּ הַמִּצְרִים פִּירָמִידוֹת עֲנָקִיּוֹת?",["כְּדֵי שֶׁיִּהְיֶה לָהֶם מָקוֹם לִשְׁמֹר אֶת הַתְּבוּאָה","כִּי חָשְׁבוּ שֶׁהָאָדָם הוּא רַק הַגּוּף","כִּי רָצוּ לִבְנוֹת מִגְדָּל שֶׁיַּגִּיעַ עַד הַשָּׁמַיִם","כְּדֵי לְהַרְאוֹת לְעַמִּים אֲחֵרִים כַּמָּה הֵם חֲכָמִים מְאוֹד"],1,"הַמִּצְרִים לֹא הֶאֱמִינוּ בַּנְּשָׁמָה. הֵם חָשְׁבוּ שֶׁהָאָדָם הוּא רַק הַגּוּף, וְלָכֵן חָנְטוּ אֶת הַמֵּתִים וּבָנוּ לָהֶם קְבָרִים מְפֹאָרִים. יְצִיאַת מִצְרַיִם הִיא שִׁחְרוּר הָרוּחַ מִן הַחֹמֶר.","פֶּרֶק א׳, הֲלָכָה ג׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["מָה קָרָה כְּשֶׁהַמִּצְרִים הִכְבִּידוּ עוֹד וָעוֹד אֶת הַשִּׁעְבּוּד?",["בְּנֵי יִשְׂרָאֵל הִתְרַבּוּ וְהִתְחַזְּקוּ עוֹד יוֹתֵר","בְּנֵי יִשְׂרָאֵל הִתְמַעֲטוּ, וְרַק מְעַטִּים נִשְׁאֲרוּ לָצֵאת","בְּנֵי יִשְׂרָאֵל בָּרְחוּ מִיָּד לַמִּדְבָּר בְּלִי לְחַכּוֹת","בְּנֵי יִשְׂרָאֵל שָׁכְחוּ אֶת שְׂפָתָם וְאֶת שְׁמוֹתֵיהֶם"],0,"״וְכַאֲשֶׁר יְעַנּוּ אֹתוֹ כֵּן יִרְבֶּה וְכֵן יִפְרֹץ״. יִשְׂרָאֵל קָלְטוּ אֶת כֹּחָהּ שֶׁל מִצְרַיִם, עַד שֶׁהָיוּ שִׁשִּׁים רִבּוֹא וְיָצְאוּ לְקַבֵּל תּוֹרָה.","פֶּרֶק א׳, הֲלָכָה ד׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["אִם הֶחָמֵץ רוֹמֵז לְגַאֲוָה, לָמָּה מֻתָּר לֶאֱכֹל אוֹתוֹ כָּל הַשָּׁנָה?",["כִּי רַק בְּפֶסַח הוּא תּוֹפֵחַ, וּבִשְׁאָר הַשָּׁנָה לֹא","כִּי כָּל הַשָּׁנָה מְשַׁכְלְלִים אֶת הָעוֹלָם, וְזֶה טוֹב","כִּי בִּזְמַן הַזֶּה אֵין בֵּית מִקְדָּשׁ וְאֵין קָרְבָּנוֹת","בֶּאֱמֶת רָאוּי לְהִמָּנַע מִמֶּנּוּ גַּם בְּכָל הַשָּׁנָה"],1,"ה׳ נָתַן לָנוּ חָכְמָה לְשַׁכְלֵל אֶת הָעוֹלָם – וְהֶחָמֵץ טוֹב. רַק בְּפֶסַח, כְּשֶׁעוֹסְקִים בְּיִסּוֹדוֹת הָאֱמוּנָה, מִתְרַחֲקִים מִכָּל ״הִתְנַפְּחוּת״ שֶׁל בְּנֵי אָדָם.","פֶּרֶק א׳, הֲלָכָה ה׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["גּוֹי אוֹכֵל פִּתָּה בְּבֵית יְהוּדִי בְּפֶסַח. מָה הַדִּין?",["אָסוּר לוֹ לְהִכָּנֵס לַבַּיִת עִם הֶחָמֵץ שֶׁלּוֹ כְּלָל","מֻתָּר, וְאֶפְשָׁר לֶאֱכֹל אִתּוֹ יַחַד עַל אוֹתוֹ שֻׁלְחָן","מֻתָּר, אֲבָל לֹא אוֹכְלִים אִתּוֹ עַל אוֹתוֹ שֻׁלְחָן","צָרִיךְ לִשְׂרֹף אֶת הַפִּתָּה שֶׁלּוֹ מִיָּד, לִפְנֵי שֶׁיֹּאכַל"],2,"חָמֵץ שֶׁל גּוֹי אֵינוֹ ״לְךָ״, וְאֵין בּוֹ ״בַּל יֵרָאֶה״. אֲבָל לֹא אוֹכְלִים אִתּוֹ עַל שֻׁלְחָן אֶחָד, שֶׁמָּא נִשְׁכַּח אוֹ שֶׁיִּפֹּל פֵּרוּר לָאֹכֶל שֶׁלָּנוּ. אַחַר כָּךְ מְנַקִּים הֵיטֵב אֶת הַשֻּׁלְחָן.","פֶּרֶק ג׳, הֲלָכָה ב׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["יְהוּדִי קִבֵּל עַל עַצְמוֹ אַחְרָיוּת לִשְׁמֹר בְּבֵיתוֹ אַרְגַּז בִּיסְקְוִיטִים שֶׁל גּוֹי. מָה הַדִּין?",["אֵין בְּעָיָה, כִּי הֶחָמֵץ שַׁיָּךְ לַגּוֹי וְלֹא לוֹ","הֶחָמֵץ נֶחְשָׁב כְּשֶׁלּוֹ, וְעָלָיו לְהַחֲזִירוֹ אוֹ לְבַעֲרוֹ","מַסְפִּיק שֶׁיְּכַסֶּה אֶת הָאַרְגָּז בְּמַגֶּבֶת בְּמֶשֶׁךְ הֶחָג","רַק הַגּוֹי חַיָּב לְבַעֵר, כִּי זֶה הֶחָמֵץ שֶׁלּוֹ"],1,"כְּשֶׁיְּהוּדִי קִבֵּל אַחְרָיוּת עַל הֶחָמֵץ, הוּא כְּאִלּוּ שֶׁלּוֹ, וְעָלָיו נֶאֱמַר ״לֹא יִמָּצֵא בְּבָתֵּיכֶם״. לָכֵן יַחֲזִיר אוֹתוֹ לַגּוֹי אוֹ יְבַעֵר אוֹתוֹ.","פֶּרֶק ג׳, הֲלָכָה ג׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["בְּמוֹצָאֵי פֶּסַח רוֹצִים לִקְנוֹת עוּגִיּוֹת. אֵיזֶה חָמֵץ מֻתָּר?",["גַּם חָמֵץ שֶׁל יְהוּדִי שֶׁשָּׁמַר אוֹתוֹ אֶצְלוֹ בְּפֶסַח","רַק חָמֵץ שֶׁנֶּאֱפָה לִפְנֵי יוֹתֵר מֵחֹדֶשׁ יָמִים","אָסוּר לִקְנוֹת שׁוּם חָמֵץ עַד אַחֲרֵי שָׁבוּעַ","חָמֵץ שֶׁל גּוֹי, אַף שֶׁעָבַר עָלָיו הַפֶּסַח"],3,"חָמֵץ שֶׁל גּוֹי שֶׁעָבַר עָלָיו הַפֶּסַח – מֻתָּר. אֲבָל חָמֵץ שֶׁל יְהוּדִי שֶׁהִשְׁאִיר אוֹתוֹ בִּרְשׁוּתוֹ בְּפֶסַח – חֲכָמִים אָסְרוּ אוֹתוֹ בַּאֲכִילָה וּבַהֲנָאָה.","פֶּרֶק ב׳, הֲלָכָה ב׳","חָמֵץ וּמַצָּה – מָה הַסּוֹד?"],["מָה הַסֵּדֶר הַנָּכוֹן שֶׁל הַשְׁבָּתַת הֶחָמֵץ?",["בִּטּוּל בַּלַּיְלָה, בְּדִיקָה בַּבֹּקֶר, וּבַסּוֹף שְׂרֵפָה","בְּדִיקָה וּבִטּוּל בַּלַּיְלָה, שְׂרֵפָה וּבִטּוּל בַּבֹּקֶר","שְׂרֵפָה בַּלַּיְלָה, וּבְדִיקָה וּבִטּוּל אֶחָד בַּבֹּקֶר","בְּדִיקָה בַּלַּיְלָה, וּבִטּוּל אֶחָד לִפְנֵי הַשְּׂרֵפָה בַּבֹּקֶר"],1,"בַּלַּיְלָה בּוֹדְקִים וּמְבַטְּלִים אֶת מָה שֶׁלֹּא נִמְצָא. בַּבֹּקֶר שׂוֹרְפִים, וְרַק אַחַר כָּךְ מְבַטְּלִים שׁוּב: מִי שֶׁמְּבַטֵּל לִפְנֵי הַשְּׂרֵפָה – הֶחָמֵץ כְּבָר אֵינוֹ שֶׁלּוֹ, וְלֹא יְקַיֵּם בּוֹ אֶת הַבִּעוּר בִּשְׂרֵפָה.","פֶּרֶק ג׳, הֲלָכָה ז׳; פֶּרֶק ה׳, הֲלָכָה ד׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["לָמָּה מְבַטְּלִים שׁוּב בַּבֹּקֶר, אִם כְּבָר בִּטְּלוּ בַּלַּיְלָה?",["כִּי בַּלַּיְלָה בִּטְּלוּ רַק אֶת הֶחָמֵץ שֶׁלֹּא נִמְצָא","כִּי בִּטּוּל שֶׁל לַיְלָה אֵינוֹ מוֹעִיל עַד הַבֹּקֶר","כִּי בַּבֹּקֶר אוֹמְרִים אֶת הַבִּטּוּל בִּשְׁבִיל הַשְּׁכֵנִים","כִּי בַּלַּיְלָה שָׁכְחוּ לוֹמַר אוֹתוֹ בַּפֶּה, וְרַק חָשְׁבוּ"],0,"בַּלַּיְלָה אִי אֶפְשָׁר לְבַטֵּל אֶת הֶחָמֵץ שֶׁשּׁוֹמְרִים לָאֲרוּחוֹת וְלַשְּׂרֵפָה – הוּא חָשׁוּב לָנוּ. בַּבֹּקֶר מְבַטְּלִים אֶת הַכֹּל, לְמִקְרֶה שֶׁמַּשֶּׁהוּ נִשְׁכַּח.","פֶּרֶק ה׳, הֲלָכָה א׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["עַד מָתַי אֶפְשָׁר לוֹמַר אֶת הַבִּטּוּל שֶׁל הַבֹּקֶר?",["עַד חֲצוֹת הַיּוֹם, כְּשֶׁמַּתְחִיל אִסּוּר הַתּוֹרָה","עַד שֶׁנִּכְנָס הֶחָג, בִּזְמַן הַדְלָקַת הַנֵּרוֹת","עַד סוֹף הַשָּׁעָה הַחֲמִישִׁית שֶׁל עֶרֶב פֶּסַח","עַד סוֹף אַרְבַּע שָׁעוֹת, כְּשֶׁאָסוּר לֶאֱכֹל"],2,"מֵהַשָּׁעָה הַשִּׁשִּׁית הֶחָמֵץ אָסוּר בַּהֲנָאָה, וְאֵינוֹ נֶחְשָׁב יוֹתֵר שֶׁלָּנוּ – וְלָכֵן כְּבָר אִי אֶפְשָׁר לְבַטֵּל אוֹתוֹ, אֶלָּא רַק לְבַעֵר אוֹתוֹ בְּפֹעַל.","פֶּרֶק ה׳, הֲלָכָה א׳; פֶּרֶק ג׳, הֲלָכָה ו׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["יוֹסִי אָמַר ״כָּל חֲמִירָא״, וְחָשַׁב שֶׁזּוֹ תְּפִלָּה לִשְׁלוֹם הֶחָג. מָה הַדִּין?",["בִּטֵּל כָּרָאוּי, כִּי אָמַר אֶת כָּל הַמִּלִּים","לֹא בִּטֵּל, כִּי לֹא הֵבִין שֶׁהוּא מְבַטֵּל","בִּטֵּל, אֲבָל רַק אֶת הֶחָמֵץ שֶׁבַּמִּטְבָּח","בִּטֵּל, כִּי אֲרָמִית הִיא שְׂפַת הַבִּטּוּל הַנְּכוֹנָה"],1,"הַבִּטּוּל הוּא הַחְלָטָה בַּלֵּב שֶׁהֶחָמֵץ כְּמוֹ עָפָר. מִי שֶׁלֹּא הֵבִין מָה הוּא אוֹמֵר – לֹא בִּטֵּל. לָכֵן אֶפְשָׁר וְרָצוּי לוֹמַר אוֹתוֹ בְּשָׂפָה שֶׁמְּבִינִים.","פֶּרֶק ה׳, הֲלָכוֹת ב׳–ג׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["חֲצִי שָׁעָה לִפְנֵי זְמַן בְּדִיקַת הֶחָמֵץ. מָה מֻתָּר לַעֲשׂוֹת?",["לְהַתְחִיל סְעוּדָה גְּדוֹלָה עִם כָּל הַמִּשְׁפָּחָה","לְהַתְחִיל לִצְבֹּעַ אֶת כָּל קִירוֹת הַבַּיִת","לָלֶכֶת לְבַקֵּר חָבֵר בָּעִיר הַשְּׁכֵנָה","לֶאֱכֹל פְּרִי אוֹ עוּגָה בְּדֶרֶךְ אֲרָעִי"],3,"חֲכָמִים אָסְרוּ לְהַתְחִיל סְעוּדָה אוֹ מְלָאכָה חֲצִי שָׁעָה לִפְנֵי הַבְּדִיקָה, שֶׁמָּא נִמָּשֵׁךְ וְנִשְׁכַּח. אֲכִילָה קְצָרָה שֶׁל פְּרִי אוֹ עוּגָה – מֻתֶּרֶת.","פֶּרֶק ד׳, הֲלָכָה ב׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["פְּרוּסָה נִתְקְעָה מֵאֲחוֹרֵי אֲרוֹן קִיר, וְאִי אֶפְשָׁר לְהוֹצִיא אוֹתָהּ בְּלִי לְפָרֵק. מָה עוֹשִׂים?",["חַיָּבִים לְפָרֵק אֶת הָאָרוֹן וּלְהוֹצִיא אוֹתָהּ","מוֹכְרִים לְגוֹי אֶת כָּל הַבַּיִת כֻּלּוֹ","מְבַטְּלִים אוֹתָהּ, וְאֵין צֹרֶךְ לְפָרֵק אֶת הָאָרוֹן","מְכַסִּים אֶת הָאָרוֹן בִּשְׂמִיכָה עַד אַחֲרֵי פֶּסַח"],2,"חָמֵץ שֶׁאִי אֶפְשָׁר לְהוֹצִיא בְּלִי לְפָרֵק אֶת הָאָרוֹן – מַסְפִּיק לְבַטֵּל אוֹתוֹ, כְּמוֹ חָמֵץ שֶׁקָּבוּר עָמֹק תַּחַת אֲבָנִים.","פֶּרֶק ד׳, הֲלָכָה י״ד","מְחַפְּשִׂים וּמְבַעֲרִים"],["בְּעֶרֶב פֶּסַח יֵשׁ חָמֵץ בְּפַח הָאַשְׁפָּה שֶׁבַּחֲצַר הַבַּיִת. מָה עוֹשִׂים לְכַתְּחִלָּה?",["שׁוֹפְכִים עָלָיו אֶקוֹנוֹמִיקָה, עַד שֶׁגַּם כֶּלֶב לֹא יֹאכַל","מַשְׁאִירִים אוֹתוֹ, כִּי מָה שֶׁבַּפַּח לֹא שַׁיָּךְ לְאַף אֶחָד","מַעֲבִירִים אֶת הַפַּח לְתוֹךְ הַבַּיִת עַד מוֹצָאֵי הֶחָג","מְכַסִּים אֶת הַפַּח בִּשְׂמִיכָה, כְּדֵי שֶׁלֹּא יִרְאוּ אוֹתוֹ"],0,"חָמֵץ בְּפַח שֶׁל הַבַּיִת עֲדַיִן בִּרְשׁוּתֵנוּ. לְכַתְּחִלָּה פּוֹגְמִים אוֹתוֹ בְּאֶקוֹנוֹמִיקָה עַד שֶׁאֵינוֹ רָאוּי לְכֶלֶב, וְאָז אֵינוֹ חָמֵץ. בְּשַׁעַת הַצֹּרֶךְ – מָה שֶׁבַּפַּח כְּבָר נֶחְשָׁב מָאוּס.","פֶּרֶק ה׳, הֲלָכָה ה׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["בְּיוֹם טוֹב שֶׁל פֶּסַח מָצָא אַבָּא עוּגִיָּה בַּסָּלוֹן. הוּא בִּטֵּל אֶת חֲמֵצוֹ לִפְנֵי הֶחָג. מָה יַעֲשֶׂה?",["יִשְׂרֹף אוֹתָהּ מִיָּד, כִּי חָמֵץ חַיָּבִים לְבַעֵר","יְכַסֶּה אוֹתָהּ בִּכְלִי, וְיִשְׂרֹף בְּמוֹצָאֵי הֶחָג","יַשְׁאִיר אוֹתָהּ בַּמָּקוֹם, כִּי הִיא כְּבָר מְבֻטֶּלֶת","יִזְרֹק אוֹתָהּ לַפַּח בַּחוּץ, וִיבָרֵךְ עַל בִּעוּרָהּ"],1,"בְּיוֹם טוֹב הֶחָמֵץ מֻקְצֶה וְאָסוּר לִשְׂרֹף אוֹתוֹ. מְכַסִּים אוֹתוֹ בִּכְלִי כְּדֵי שֶׁלֹּא יֹאכְלוּ בְּטָעוּת, וּבְמוֹצָאֵי הֶחָג שׂוֹרְפִים – בְּלִי בְּרָכָה.","פֶּרֶק ה׳, הֲלָכָה ו׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["אַבָּא חָלָה בְּלֵיל י״ד וְאֵינוֹ יָכוֹל לִבְדֹּק חָמֵץ. מָה עוֹשִׂים?",["מְדַלְּגִים הַשָּׁנָה עַל הַבְּדִיקָה, וּמַסְתַּפְּקִים בַּבִּטּוּל","אִמָּא אוֹ אֶחָד מִבְּנֵי הַבַּיִת הַגְּדוֹלִים בּוֹדְקִים בִּמְקוֹמוֹ","מְחַכִּים שֶׁאַבָּא יַבְרִיא, וּבוֹדְקִים בְּאֶמְצַע הַפֶּסַח","רַק אִישׁ יָכוֹל לִבְדֹּק, וְלָכֵן קוֹרְאִים לַשָּׁכֵן"],1,"חוֹבַת הַבְּדִיקָה עַל בַּעַל הַבַּיִת, וּכְשֶׁקָּשֶׁה לוֹ – הוּא מְמַנֶּה אֶת אִשְׁתּוֹ אוֹ אֶחָד מִבְּנֵי הַבַּיִת הַגְּדוֹלִים, שֶׁאֶפְשָׁר לִסְמֹךְ עָלָיו שֶׁיִּבְדֹּק כָּרָאוּי. בְּמִצְוָה זוֹ אֵין הֶבְדֵּל בֵּין אִישׁ לְאִשָּׁה, וְהַבּוֹדֵק מְבָרֵךְ.","פֶּרֶק ד׳, הֲלָכוֹת א׳, ט׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["מִן הַתּוֹרָה מַסְפִּיק לְבַטֵּל אֶת הֶחָמֵץ בַּלֵּב. לָמָּה חֲכָמִים תִּקְּנוּ גַּם לְבַעֵר אוֹתוֹ מִן הַבַּיִת?",["שֶׁמָּא יְבַטֵּל בְּלִי לֵב שָׁלֵם, אוֹ יִרְאֶה חָמֵץ וְיֹאכַל","כִּי בִּטּוּל בַּלֵּב מוֹעִיל רַק לְמִי שֶׁהוּא כְּבָר בַּר מִצְוָה","כְּדֵי שֶׁיִּהְיֶה לָנוּ עוֹד חָמֵץ לִשְׂרֹף בְּבֹקֶר עֶרֶב פֶּסַח","כִּי בְּלִי שְׂרֵפָה אֵין שׁוּם מִצְוָה בְּבִעוּר הֶחָמֵץ"],0,"חֲכָמִים חָשְׁשׁוּ שֶׁמָּא מִישֶׁהוּ לֹא יְבַטֵּל בְּלֵב שָׁלֵם וְיַשְׁאִיר חָמֵץ לְאַחַר הַפֶּסַח, אוֹ שֶׁיִּשָּׁאֵר חָמֵץ בַּבַּיִת וְיֹאכְלוּ אוֹתוֹ בְּטָעוּת. וּמִצַּד שֵׁנִי לֹא סָמְכוּ רַק עַל הַבְּדִיקָה, שֶׁמָּא לֹא יִמְצְאוּ הַכֹּל. לָכֵן עוֹשִׂים גַּם וְגַם.","פֶּרֶק ג׳, הֲלָכָה ד׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["לָמָּה מִשְׁתַּדְּלִים שֶׁיִּהְיֶה בַּבַּיִת מְעַט חָמֵץ בְּבֹקֶר עֶרֶב פֶּסַח?",["כְּדֵי לְקַיֵּם בּוֹ אֶת מִצְוַת הַשְׁבָּתַת הֶחָמֵץ לְכָל הַדֵּעוֹת","כְּדֵי שֶׁיִּהְיֶה לַיְּלָדִים מָה לֶאֱכֹל בְּלֵיל הַסֵּדֶר לִפְנֵי הַמַּצָּה","כְּדֵי לִמְכֹּר אוֹתוֹ לַגּוֹי בְּתוֹךְ יְמֵי הַפֶּסַח","כִּי אָסוּר שֶׁהַבַּיִת יִהְיֶה נָקִי לְגַמְרֵי לִפְנֵי הַבְּדִיקָה"],0,"לְדַעַת רֹב הָרִאשׁוֹנִים, הַמִּצְוָה הִיא שֶׁהַבַּיִת יִהְיֶה נָקִי מֵחָמֵץ. אֲבָל לְדַעַת כַּמָּה רִאשׁוֹנִים, מְקַיְּמִים אֶת הַמִּצְוָה רַק כְּשֶׁמְּבַעֲרִים חָמֵץ בְּפֹעַל. לָכֵן יִשְׂרָאֵל קְדוֹשִׁים מַשְׁאִירִים מְעַט חָמֵץ – וְשׂוֹרְפִים אוֹתוֹ.","פֶּרֶק ג׳, הֲלָכָה ה׳","מְחַפְּשִׂים וּמְבַעֲרִים"],["מִשְׁפַּחַת גִּלְעָד לֹא הִסְפִּיקָה לִבְדֹּק חָמֵץ בְּלֵיל י״ד. מָה עוֹשִׂים?",["בּוֹדְקִים בְּיוֹם י״ד, בִּבְרָכָה, כְּמוֹ בַּלַּיְלָה","לֹא בּוֹדְקִים כְּלָל, וּמַסְפִּיק לְבַטֵּל אֶת הֶחָמֵץ בַּבֹּקֶר","בּוֹדְקִים בְּיוֹם י״ד, אֲבָל בְּלִי בְּרָכָה, כִּי עָבַר הַזְּמַן","מְחַכִּים לְמוֹצָאֵי הֶחָג, וּבוֹדְקִים אָז אֶת כָּל הַבַּיִת"],0,"מִי שֶׁלֹּא בָּדַק בְּלֵיל י״ד – בּוֹדֵק בְּיוֹם י״ד בִּבְרָכָה. אִם לֹא בָּדַק לִפְנֵי הַפֶּסַח – בּוֹדֵק בַּפֶּסַח בִּבְרָכָה. וְאִם נִזְכַּר רַק אַחֲרֵי הַפֶּסַח – בּוֹדֵק בְּלִי בְּרָכָה.","פֶּרֶק ד׳, הֲלָכָה י״ב","מְחַפְּשִׂים וּמְבַעֲרִים"],["לָמָּה צָרִיךְ לִבְדֹּק חָמֵץ גַּם בְּבֵית כְּנֶסֶת שֶׁלֹּא אוֹכְלִים בּוֹ?",["כִּי לִפְעָמִים נִכְנָסִים אֵלָיו יְלָדִים קְטַנִּים עִם מַאַכְלֵי חָמֵץ","כִּי בֵּית כְּנֶסֶת קָדוֹשׁ יוֹתֵר, וְצָרִיךְ לְנַקּוֹת אוֹתוֹ פַּעֲמַיִם","כִּי בְּבֵית הַכְּנֶסֶת אוֹמְרִים אֶת נֻסַּח הַבִּטּוּל לְכָל הַקָּהָל","כִּי הַגַּבַּאי צָרִיךְ לִמְכֹּר אֶת חָמֵץ בֵּית הַכְּנֶסֶת לַגּוֹי"],0,"בָּתֵּי כְּנֶסֶת וּבָתֵּי מִדְרָשׁ צְרִיכִים בְּדִיקָה, כִּי לִפְעָמִים אוֹכְלִים בָּהֶם, וְגַם כְּשֶׁלֹּא – נִכְנָסִים יְלָדִים עִם חָמֵץ. הַבּוֹדֵק אֶת בֵּית הַכְּנֶסֶת בּוֹדֵק קֹדֶם אֶת בֵּיתוֹ, וּמְכַוֵּן בַּבְּרָכָה גַּם עַל בֵּית הַכְּנֶסֶת.","פֶּרֶק ד׳, הֲלָכָה י״ג","מְחַפְּשִׂים וּמְבַעֲרִים"],["לָמָּה מַקְפִּידִים לַעֲשׂוֹת אֶת מְכִירַת הֶחָמֵץ בְּכָל סוּגֵי הַקִּנְיָנִים?",["כְּדֵי שֶׁהַמְּכִירָה תִּהְיֶה אֲמִתִּית וּתְקֵפָה לְפִי כָּל הַדֵּעוֹת","כְּדֵי שֶׁהַגּוֹי יְשַׁלֵּם מְחִיר גָּבוֹהַּ יוֹתֵר עַל הֶחָמֵץ","כְּדֵי שֶׁיִּהְיֶה אֶפְשָׁר לֶאֱכֹל מֵהֶחָמֵץ גַּם בְּתוֹךְ פֶּסַח","כִּי כָּךְ הַמּוֹכֵר פָּטוּר מִבְּדִיקַת חָמֵץ בְּלֵיל י״ד"],0,"יֵשׁ דֵּעוֹת שׁוֹנוֹת אֵיזֶה קִנְיָן מוֹעִיל בֵּין יְהוּדִי לְגוֹי, וְלָכֵן עוֹשִׂים אֶת כֻּלָּם – כְּדֵי שֶׁהַמְּכִירָה תָּחוּל לְפִי כָּל הַדֵּעוֹת וְלֹא תֵּרָאֶה כְּהַעֲרָמָה.","פֶּרֶק ו׳, הֲלָכָה ב׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["מָתַי מֻתָּר לְהַתְחִיל לֶאֱכֹל מֵהֶחָמֵץ שֶׁמָּכַרְנוּ?",["מִיָּד בְּלֵיל שְׁבִיעִי שֶׁל פֶּסַח, אַחֲרֵי הַקִּדּוּשׁ","רַק אַחֲרֵי שֶׁעוֹבֵר חֹדֶשׁ שָׁלֵם מִסּוֹף הֶחָג","אַחֲרֵי פֶּסַח, כְּשֶׁהָרַבָּנוּת כְּבָר קָנְתָה אוֹתוֹ בַּחֲזָרָה","אַף פַּעַם, כִּי הוּא כְּבָר שַׁיָּךְ לַגּוֹי לְעוֹלָם"],2,"אַחֲרֵי פֶּסַח מַמְתִּינִים מְעַט, עַד שֶׁאֶפְשָׁר לְשַׁעֵר שֶׁהָרַבָּנוּת קָנְתָה אֶת הֶחָמֵץ בַּחֲזָרָה בִּשְׁבִיל כֻּלָּם – וְאָז, לְדַעַת רֹב הַפּוֹסְקִים, מֻתָּר לְהִשְׁתַּמֵּשׁ בּוֹ. יֵשׁ נוֹהֲגִים לְהַחְמִיר וְלֹא לֶאֱכֹל מֵחָמֵץ שֶׁנִּמְכַּר.","פֶּרֶק ו׳, הֲלָכָה ו׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["אַחֲרֵי פֶּסַח רוֹצִים לִקְנוֹת לֶחֶם בְּמַכֹּלֶת. מָה צָרִיךְ לִבְדֹּק?",["שֶׁהַלֶּחֶם נֶאֱפָה לְפָחוֹת שָׁבוּעַ לִפְנֵי פֶּסַח","שֶׁהַמּוֹכֵר הוּא תַּלְמִיד חָכָם וְיוֹדֵעַ הֲלָכוֹת","שֶׁיֵּשׁ לַמּוֹכֵר תְּעוּדָה שֶׁמָּכַר אֶת חֲמֵצוֹ כַּדִּין","שֶׁהַלֶּחֶם עָטוּף הֵיטֵב, וְלֹא נָגַע בּוֹ אַף אֶחָד"],2,"חָמֵץ שֶׁל יְהוּדִי שֶׁעָבַר עָלָיו הַפֶּסַח אָסוּר. לָכֵן בּוֹדְקִים שֶׁהַמּוֹכֵר מָכַר אֶת חֲמֵצוֹ כַּדִּין, וְנִזְהַר שֶׁלֹּא לָגַעַת בּוֹ בְּפֶסַח.","פֶּרֶק ו׳, הֲלָכָה ו׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["עוּגָה מִקֶּמַח חִטָּה נִלּוֹשָׁה רַק בְּמִיץ תַּפּוּחִים, בְּלִי טִפַּת מַיִם. מָה נָכוֹן?",["הִיא חָמֵץ גָּמוּר מִן הַתּוֹרָה, לְכָל הָעֵדוֹת","מִן הַדִּין אֵינָהּ חָמֵץ, וְהָאַשְׁכְּנַזִּים נוֹהֲגִים לֹא לְאָכְלָהּ","יוֹצְאִים בָּהּ יְדֵי מִצְוַת מַצָּה בְּלֵיל הַסֵּדֶר","מֻתֶּרֶת לְכֻלָּם, גַּם אִם הוֹסִיפוּ לַבָּצֵק מְעַט מַיִם"],1,"מִיץ פֵּרוֹת בְּלִי מַיִם אֵינוֹ מַחְמִיץ. הָאַשְׁכְּנַזִּים נוֹהֲגִים לֹא לֶאֱכֹל מַצָּה עֲשִׁירָה (חוּץ מֵחוֹלֶה אוֹ זָקֵן), וּלְמִנְהַג הַסְּפָרַדִּים הִיא מֻתֶּרֶת מִן הַדִּין – וְרַבִּים מֵהֶם מַחְמִירִים הַיּוֹם, כִּי מוֹסִיפִים לַמִּיץ מַיִם.","פֶּרֶק ח׳, הֲלָכָה א׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["מֻתָּר לָשִׂים מַצָּה בְּתוֹךְ מָרָק חַם בְּפֶסַח?",["לֹא, כִּי מַצָּה שֶׁנִּרְטֶבֶת חוֹזֶרֶת לִהְיוֹת בָּצֵק","כֵּן, כִּי מַצָּה אֲפוּיָה אֵינָהּ יְכוֹלָה לְהַחְמִיץ","רַק אִם הַמָּרָק רוֹתֵחַ מְאוֹד, וְלֹא פּוֹשֵׁר","רַק לְחוֹלִים, כִּי בְּדֶרֶךְ כְּלָל זֶה חָמֵץ"],1,"אַחֲרֵי שֶׁהַמַּצָּה נֶאֶפְתָה הֵיטֵב, כֹּחַ הַחִמּוּץ שֶׁבַּקֶּמַח בָּטֵל, וְכָךְ נוֹהֲגִים רֹב יִשְׂרָאֵל. הַחֲסִידִים נָהֲגוּ לְהַחְמִיר שֶׁלֹּא לֶאֱכֹל מַצָּה שְׁרוּיָה, וְאֵין לְזַלְזֵל בְּמִנְהָגָם.","פֶּרֶק ח׳, הֲלָכָה ב׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["מָה אֶחָד הַטְּעָמִים לְמִנְהַג הָאַשְׁכְּנַזִּים שֶׁלֹּא לֶאֱכֹל קִטְנִיּוֹת?",["קִטְנִיּוֹת מַחְמִיצוֹת בְּדִיּוּק כְּמוֹ חִטָּה, וְזֶה אִסּוּר תּוֹרָה","גַּרְגְּרֵי חִטָּה מִתְעָרְבִים לִפְעָמִים בְּתוֹךְ הַקִּטְנִיּוֹת","קִטְנִיּוֹת הֵן מַאֲכַל עֲשִׁירִים, וּבְפֶסַח זוֹכְרִים אֶת הָעֹנִי","בִּימֵי הַתַּלְמוּד כָּל חַכְמֵי יִשְׂרָאֵל אָסְרוּ קִטְנִיּוֹת"],1,"בַּשָּׂדוֹת וּבַמַּחְסָנִים מִתְעָרְבִים בַּקִּטְנִיּוֹת גַּרְגְּרֵי חִטָּה, וְהֵם עֲלוּלִים לְהַחְמִיץ בַּבִּשּׁוּל. קִטְנִיּוֹת עַצְמָן אֵינָן חָמֵץ מִן הַתּוֹרָה, וּבִימֵי הַתַּלְמוּד אָכְלוּ אֹרֶז בְּפֶסַח.","פֶּרֶק ט׳, הֲלָכָה א׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["מִשְׁפָּחָה סְפָרַדִּית אוֹכֶלֶת אֹרֶז בְּפֶסַח. עַל מָה עָלֶיהָ לְהַקְפִּיד?",["לְבַשֵּׁל אוֹתוֹ רַק בְּסִירִים שֶׁל חָמֵץ","לֶאֱכֹל אוֹתוֹ רַק בְּחֹל הַמּוֹעֵד, וְלֹא בֶּחָג","לִקְנוֹת בְּהַשְׁגָּחָה לְפֶסַח, אוֹ לִבְדֹּק שָׁלֹשׁ פְּעָמִים","אֵין צֹרֶךְ בִּבְדִיקָה, כִּי אֹרֶז אֵינוֹ דָּגָן"],2,"הָאֹרֶז נֶאֱרָז הַיּוֹם בְּמָקוֹם שֶׁאוֹרְזִים קְמָחִים וְסֹלֶת, וְלָכֵן הָאוֹכְלִים אֹרֶז קוֹנִים אוֹתוֹ בְּהַשְׁגָּחָה מְיֻחֶדֶת לְפֶסַח, אוֹ בּוֹדְקִים אוֹתוֹ הֵיטֵב שָׁלֹשׁ פְּעָמִים.","פֶּרֶק ט׳, הֲלָכָה ב׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["אִמָּא בָּאָה מִמִּשְׁפָּחָה שֶׁלֹּא אוֹכֶלֶת קִטְנִיּוֹת, וְאַבָּא מִמִּשְׁפָּחָה שֶׁאוֹכֶלֶת. מָה הַדִּין?",["כָּל אֶחָד מֵהֶם אוֹכֵל לְבַד, לְפִי מִנְהַג בֵּית אָבִיו","אִמָּא נוֹהֶגֶת כְּמִנְהַג אַבָּא, וְאוֹכֶלֶת קִטְנִיּוֹת","אַבָּא צָרִיךְ לְהַחְמִיר כְּמוֹתָהּ, כְּדֵי שֶׁיֹּאכְלוּ יַחַד","אִמָּא צְרִיכָה הַתָּרַת נְדָרִים לִפְנֵי שֶׁתֹּאכַל קִטְנִיּוֹת"],1,"אִשָּׁה נוֹהֶגֶת כְּמִנְהֲגֵי בַּעְלָהּ, כְּמוֹ מִי שֶׁעָבַר לָגוּר לְתָמִיד בְּמָקוֹם חָדָשׁ. כָּךְ כָּל הַמִּשְׁפָּחָה יוֹשֶׁבֶת סְבִיב שֻׁלְחָן אֶחָד, וְאֵין צֹרֶךְ בְּהַתָּרַת נְדָרִים.","פֶּרֶק ט׳, הֲלָכָה ג׳","מְכִירַת חָמֵץ, כַּשְׁרוּת וְקִטְנִיּוֹת"],["בְּלֵיל הַסֵּדֶר יֵשׁ לְאַבָּא רַק מַצּוֹת מְכוֹנָה שְׁמוּרוֹת, עִם הַשְׁגָּחָה טוֹבָה. מָה הַדִּין?",["אֵין יוֹצְאִים בָּהֶן, כִּי מְכוֹנָה לֹא יְכוֹלָה לְכַוֵּן","יוֹצְאִים, אֲבָל רַק אִם אוֹכְלִים מֵהֶן מַצָּה שְׁלֵמָה","יוֹצְאִים, כִּי הָאָדָם הִפְעִיל אֶת הַמְּכוֹנָה לְשֵׁם מִצְוָה","יוֹצְאִים רַק אִם גַּם אוֹפִים אוֹתָן שׁוּב בַּבַּיִת"],2,"רֹב הַפּוֹסְקִים אוֹמְרִים שֶׁיּוֹצְאִים בְּמַצּוֹת מְכוֹנָה, כִּי הָאָדָם שֶׁמַּפְעִיל אֶת הַמְּכוֹנָה מְכַוֵּן לְשֵׁם מַצַּת מִצְוָה. וְרַבִּים מְהַדְּרִים בְּמַצַּת יָד לַכְּזֵיתִים שֶׁל הַמִּצְוָה.","פֶּרֶק י״ב, הֲלָכָה ד׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["אֵילּוּ מַצּוֹת כְּשֵׁרוֹת לְכַתְּחִלָּה לְכָל יְמֵי הַפֶּסַח?",["רַק מַצּוֹת יָד שֶׁנִּשְׁמְרוּ מִשְּׁעַת הַקְּצִירָה","גַּם מַצּוֹת רְגִילוֹת, שְׁמוּרוֹת מִשְּׁעַת טְחִינָה","גַּם מַצּוֹת מִקֶּמַח רָגִיל שֶׁל הַחֲנוּת","רַק מַצּוֹת שֶׁנֶּאֶפוּ אַחֲרֵי חֲצוֹת שֶׁל עֶרֶב פֶּסַח"],1,"הַמַּצּוֹת הָרְגִילוֹת שְׁמוּרוֹת מִשְּׁעַת טְחִינָה וּכְשֵׁרוֹת לְכַתְּחִלָּה לְכָל הַפֶּסַח. הַמְּהַדְּרִים אוֹכְלִים שְׁמוּרוֹת מִשְּׁעַת קְצִירָה. וְקֶמַח מֵהַחֲנוּת בְּלִי הַשְׁגָּחָה – יֵשׁ חֲשַׁשׁ שֶׁהֶחְמִיץ.","פֶּרֶק י״ב, הֲלָכוֹת ב׳, ה׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["מַה דִּינָהּ שֶׁל ״מַצָּה עֲשִׁירָה״, שֶׁנִּלּוֹשָׁה בְּיַיִן וְשֶׁמֶן?",["מֻתֶּרֶת לְכֻלָּם, כִּי אֵין בָּהּ מַיִם בִּכְלָל","לַסְּפָרַדִּים מֻתֶּרֶת מִן הַדִּין, וְלָאַשְׁכְּנַזִּים אֲסוּרָה","לָאַשְׁכְּנַזִּים מֻתֶּרֶת מִן הַדִּין, וְלַסְּפָרַדִּים אֲסוּרָה","אֲסוּרָה לְכֻלָּם, כִּי הִיא חָמֵץ גָּמוּר"],1,"לְמִנְהַג הַסְּפָרַדִּים מַצָּה עֲשִׁירָה מֻתֶּרֶת מִן הַדִּין, וּלְמִנְהַג הָאַשְׁכְּנַזִּים אֲסוּרָה. וְכַיּוֹם, בִּגְלַל סְפֵקוֹת בַּיִּצּוּר, רַבִּים מֵהַפּוֹסְקִים אוֹמְרִים שֶׁגַּם הַסְּפָרַדִּים יִמָּנְעוּ מִמֶּנָּה.","פֶּרֶק י״ג, הֲלָכָה ז׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["עֶרֶב פֶּסַח, שָׁלֹשׁ שָׁעוֹת לִפְנֵי הַחַג. אֵיתָן רָעֵב מְאוֹד. מָה מֻתָּר לוֹ לֶאֱכֹל?",["עוּגָה גְּדוֹלָה וּטְעִימָה שֶׁנֶּאֱפְתָה מִקֶּמַח מַצָּה","קְעָרָה מְלֵאָה שֶׁל קְצִיצוֹת קֶמַח מַצָּה","מְעַט פֵּרוֹת אוֹ יְרָקוֹת בִּלְבַד","חֲתִיכָה קְטַנָּה שֶׁל מַצָּה שְׁמוּרָה"],2,"מֵהַשָּׁעָה הָעֲשִׂירִית לֹא אוֹכְלִים מִינֵי מְזוֹנוֹת, כְּדֵי לֶאֱכֹל אֶת הַמַּצָּה בַּלַּיְלָה בְּתֵאָבוֹן. מֻתָּר לֶאֱכֹל מְעַט פֵּרוֹת, יְרָקוֹת, בָּשָׂר אוֹ דָּגִים. מַצָּה אֲסוּרָה כָּל הַיּוֹם.","פֶּרֶק י״ג, הֲלָכָה ז׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["לָמָּה, לְפִי הַמַּהֲרַ״ל, אָסוּר לִשְׁבֹּר עֶצֶם בְּקָרְבַּן הַפֶּסַח?",["כִּי הָעֲצָמוֹת הָיוּ שַׁיָּכוֹת לַכֹּהֲנִים בַּמִּקְדָּשׁ","כִּי הַשְּׁבִירָה מְבַטֵּאת פֵּרוּד, וְהַפֶּסַח מְבַטֵּא אַחְדּוּת","כְּדֵי שֶׁלֹּא יִתְעַכְּבוּ וְיִגְמְרוּ לֶאֱכֹל אַחֲרֵי חֲצוֹת","כִּי בַּעֲצָמוֹת הַשְּׁבוּרוֹת יֵשׁ חֲשַׁשׁ שֶׁל חָמֵץ"],1,"הַפֶּסַח מְבַטֵּא אֶת אַחְדּוּת ה׳ וְאַחְדּוּת יִשְׂרָאֵל. לָכֵן אוֹכְלִים אוֹתוֹ בַּחֲבוּרָה, צוֹלִים אוֹתוֹ שֶׁהַבָּשָׂר יִתְאַחֵד, וְלֹא שׁוֹבְרִים בּוֹ עֶצֶם – כִּי שְׁבִירָה הִיא פֵּרוּד.","פֶּרֶק י״ג, הֲלָכָה ח׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["עֶרֶב פֶּסַח חָל בְּשַׁבָּת. בַּמֶּה אוֹכְלִים סְעוּדָה שְׁלִישִׁית?",["בְּלֶחֶם, כִּי שְׁאַר הַחָמֵץ עוֹד מֻתָּר","בְּמַצָּה שְׁמוּרָה, כִּי כְּבָר אָסוּר לֶאֱכֹל חָמֵץ","בְּבָשָׂר, דָּגִים אוֹ פֵּרוֹת, וְלֹא מַרְבִּים בָּהּ","לֹא אוֹכְלִים אוֹתָהּ, וְצָמִים עַד הַסֵּדֶר"],2,"חָמֵץ אָסוּר מִסּוֹף הַשָּׁעָה הָרְבִיעִית, וּמַצָּה אֲסוּרָה כָּל יוֹם י״ד. לָכֵן יוֹצְאִים בְּבָשָׂר, דָּגִים, פֵּרוֹת אוֹ קְצִיצוֹת מַצָּה מְבֻשָּׁלוֹת – וְלֹא מַרְבִּים, כְּדֵי לֶאֱכֹל בַּלַּיְלָה בְּתֵאָבוֹן.","פֶּרֶק י״ד, הֲלָכָה א׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["עֶרֶב פֶּסַח חָל בְּשַׁבָּת. מָתַי עוֹרְכִים אֶת שֻׁלְחַן הַסֵּדֶר?",["בְּשַׁבָּת בַּצָּהֳרַיִם, כְּדֵי שֶׁיִּהְיֶה מוּכָן בַּזְּמַן","בְּיוֹם חֲמִישִׁי, יַחַד עִם תַּעֲנִית הַבְּכוֹרוֹת","רַק בְּמוֹצָאֵי שַׁבָּת, אַחֲרֵי צֵאת הַכּוֹכָבִים","בְּשַׁבָּת אַחֲרֵי מִנְחָה, כִּי כְּבָר אַחֲרֵי חֲצוֹת"],2,"אָסוּר לְהָכִין מִשַּׁבָּת לְיוֹם טוֹב, וְלָכֵן עוֹרְכִים אֶת הַשֻּׁלְחָן מִיָּד אַחֲרֵי צֵאת הַשַּׁבָּת. אֶת הַתַּבְשִׁילִים, הַחֲרֹסֶת וְהַזְּרוֹעַ טוֹב לְהָכִין כְּבָר בְּיוֹם שִׁשִּׁי.","פֶּרֶק י״ד, הֲלָכָה ב׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["בְּחֹל הַמּוֹעֵד פֶּסַח אוֹכֵל אֶפְרַיִם מַצָּה בִּסְעוּדַת הַצָּהֳרַיִם. הַאִם הוּא מְקַיֵּם מִצְוָה?",["לֹא, כִּי אָסוּר לֶאֱכֹל מַצָּה אַחֲרֵי לֵיל הַסֵּדֶר","כֵּן, וְהוּא מְבָרֵךְ ״עַל אֲכִילַת מַצָּה״ בְּכָל סְעוּדָה","אֵין חוֹבָה, אֲבָל לְדַעַת רַבִּים – הָאוֹכֵל מְקַיֵּם מִצְוָה","כֵּן, וְכָל מַה שֶּׁיֹּאכַל יוֹתֵר – מוֹסִיף עוֹד מִצְוָה"],2,"חוֹבַת אֲכִילַת מַצָּה הִיא רַק בְּלֵיל הַסֵּדֶר, וְרַק עָלֶיהָ מְבָרְכִים ״עַל אֲכִילַת מַצָּה״. אֲבָל גְּדוֹלֵי יִשְׂרָאֵל רַבִּים כָּתְבוּ שֶׁגַּם בִּשְׁאָר יְמֵי הַפֶּסַח הָאוֹכֵל מַצָּה מְקַיֵּם מִצְוָה – כְּזַיִת בְּכָל סְעוּדָה, וְהָאוֹכֵל יוֹתֵר אֵינוֹ מוֹסִיף מִצְוָה.","פֶּרֶק י״ב, הֲלָכָה א׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["מִי יָכוֹל לָלוּשׁ וְלֶאֱפוֹת מַצּוֹת מִצְוָה לְלֵיל הַסֵּדֶר?",["כָּל אֶחָד, גַּם יְלָדִים קְטַנִּים, אִם הֵם זְרִיזִים מְאוֹד","יְהוּדִים בְּנֵי מִצְוָה, שֶׁמְּכַוְּנִים ״לְשֵׁם מַצַּת מִצְוָה״","רַק כֹּהֲנִים, כִּי הַמַּצָּה זֵכֶר לְקָרְבַּן הַפֶּסַח","גַּם גּוֹיִים, אִם יְהוּדִי עוֹמֵד לְיָדָם וּמַשְׁגִּיחַ עַל הָעֲבוֹדָה"],1,"הַשְּׁמִירָה שֶׁל מַצַּת מִצְוָה הִיא גַּם מֵחִמּוּץ וְגַם בְּכַוָּנָה. לָכֵן אֶת הַלִּישָׁה וְהָאֲפִיָּה עוֹשִׂים יְהוּדִים בְּנֵי מִצְוָה, שֶׁמְּכַוְּנִים לְשֵׁם מַצַּת מִצְוָה. רַק אֶת הַקְּצִירָה וְהַטְּחִינָה מֻתָּר לְגוֹיִים לַעֲשׂוֹת, כְּשֶׁיְּהוּדִי מַשְׁגִּיחַ.","פֶּרֶק י״ב, הֲלָכָה ג׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["בְּעֶרֶב פֶּסַח, אַחֲרֵי חֲצוֹת הַיּוֹם, רוֹצֶה נָתָן לְהִסְתַּפֵּר. מָה הַדִּין?",["מֻתָּר, כִּי תִּסְפֹּרֶת הִיא הֲכָנָה לִכְבוֹד הֶחָג","אָסוּר, כִּי מֵחֲצוֹת הַיּוֹם אָסוּר לַעֲשׂוֹת מְלָאכָה חֲשׁוּבָה","מֻתָּר, כִּי הָאִסּוּר הוּא רַק עַל מְלֶאכֶת כֶּסֶף וְעֵסֶק","אָסוּר, כִּי מִן הַבֹּקֶר אָסוּר לַעֲשׂוֹת כָּל דָּבָר"],1,"מֵחֲצוֹת יוֹם י״ד אָסוּר לַעֲשׂוֹת מְלָאכָה חֲשׁוּבָה – כְּמוֹ תְּפִירָה, בְּנִיָּה וְתִסְפֹּרֶת. הַמִּנְהָג הָרוֹוֵחַ לַעֲבֹד עַד חֲצוֹת. בִּשּׁוּל, נִקָּיוֹן, גִּהוּץ וּגְזִיזַת צִפָּרְנַיִם – מֻתָּרִים.","פֶּרֶק י״ג, הֲלָכָה א׳","מַצָּה שְׁמוּרָה וְעֶרֶב פֶּסַח"],["הַבֵּן הָרָשָׁע אוֹמֵר: ״מָה הָעֲבֹדָה הַזֹּאת לָכֶם״. מָה לוֹמְדִים מִכָּךְ שֶׁהַתּוֹרָה מְצַוָּה לַעֲנוֹת לוֹ?",["שֶׁעוֹנִים לוֹ רַק כְּדֵי לְהוֹכִיחַ אוֹתוֹ לִפְנֵי כֻּלָּם","שֶׁתָּמִיד מַאֲמִינִים שֶׁאוּלַי הַדְּבָרִים יִכָּנְסוּ לְלִבּוֹ","שֶׁהוּא צָרִיךְ לָשֶׁבֶת לְבַד, רָחוֹק מֵהַשֻּׁלְחָן","שֶׁאֵין לוֹ חֵלֶק בַּסֵּדֶר, וְלָכֵן לֹא מְסַפְּרִים לוֹ"],1,"הַתּוֹרָה מְצַוָּה לְהִתְיַחֵס גַּם אֵלָיו וּלְהַסְבִּיר לוֹ אֶת סְגֻלַּת יִשְׂרָאֵל, כִּי תָּמִיד צָרִיךְ לְהַאֲמִין שֶׁאוּלַי יִכָּנְסוּ הַדְּבָרִים לְלִבּוֹ, וְהוּא יַעֲבִיר אֶת לַפִּיד הַמָּסֹרֶת הָלְאָה.","פֶּרֶק ט״ו, הֲלָכָה ה׳","וְהִגַּדְתָּ לְבִנְךָ"],["הַבֵּן הַתָּם שׁוֹאֵל רַק: ״מַה זֹּאת?״. מָה מַסְבִּירִים לוֹ?",["אֶת כָּל הַחֻקִּים וְהַמִּשְׁפָּטִים שֶׁל הַפֶּסַח, בִּפְרוֹטְרוֹט","אֶת הַמַּכּוֹת וְאֶת לֵב פַּרְעֹה הַקָּשֶׁה","רַק ״בַּעֲבוּר זֶה״, בְּלִי לְסַפֵּר אֶת הַסִּפּוּר","שֶׁהוּא יָבִין כְּשֶׁיִּגְדַּל, וְעַכְשָׁו אֵין צֹרֶךְ"],1,"לַתָּם מַסְבִּירִים לְפִי הֲבָנָתוֹ אֶת הַמְּאֹרָעוֹת הַמַּרְשִׁימִים: הַמַּכּוֹת הַגְּדוֹלוֹת וְקַשְׁיוּת לִבּוֹ שֶׁל פַּרְעֹה, שֶׁנִּשְׁבְּרָה בְּמַכַּת בְּכוֹרוֹת. הַתְּשׁוּבָה הָאֲרֻכָּה וְהַמְּפֹרֶטֶת – לֶחָכָם.","פֶּרֶק ט״ו, הֲלָכָה ה׳","וְהִגַּדְתָּ לְבִנְךָ"],["בְּאֶמְצַע הַהַגָּדָה רוֹאֶה אַבָּא שֶׁהַקְּטַנִּים מַתְחִילִים לְהֵרָדֵם. מָה יַעֲשֶׂה?",["יְדַלֵּג מִיָּד לַסְּעוּדָה, וְאֶת הַשְּׁאָר יַשְׁלִימוּ מָחָר","יַשְׁכִּיב אוֹתָם לִישֹׁן, כִּי יְלָדִים פְּטוּרִים מֵהַסִּפּוּר","יֹאמַר לָהֶם פֶּסַח, מַצָּה וּמָרוֹר וּמַשְׁמָעוּתָם","יִקְרָא מַהֵר אֶת כָּל הַהַגָּדָה בְּלִי לְהַסְבִּיר"],2,"כְּדֵי לָצֵאת יְדֵי מִצְוַת הַסִּפּוּר צָרִיךְ לְפָחוֹת לוֹמַר אוֹ לִשְׁמֹעַ פֶּסַח, מַצָּה וּמָרוֹר וּמַשְׁמָעוּתָם. לָכֵן הוֹרִים שֶׁרוֹאִים שֶׁהַיְּלָדִים נִרְדָּמִים – אוֹמְרִים לָהֶם קֹדֶם אֶת שְׁלֹשֶׁת הַדְּבָרִים הָאֵלֶּה.","פֶּרֶק ט״ז, הֲלָכָה י״ח","וְהִגַּדְתָּ לְבִנְךָ"],["בְּ״וְהִיא שֶׁעָמְדָה״ מַגְבִּיהִים אֶת הַכּוֹס. לָמָּה מְכַסִּים אָז אֶת הַמַּצּוֹת?",["כְּדֵי שֶׁלֹּא יִפֹּל עֲלֵיהֶן יַיִן מֵהַכּוֹס","כְּדֵי שֶׁהַיְּלָדִים לֹא יִקְחוּ מֵהֶן בְּלִי רְשׁוּת","כִּי לֹא נִרְאֶה כְּמִי שֶׁמְּכַבֵּד אֶת הַיַּיִן יוֹתֵר","כִּי אֶת הַחֵלֶק הַזֶּה אוֹמְרִים בְּלִי מַצָּה בִּכְלָל"],2,"הַמַּצָּה חֲשׁוּבָה מֵהַיַּיִן. כְּשֶׁמַּקְדִּימִים אֶת הַכּוֹס וּמַגְבִּיהִים אוֹתָהּ, מְכַסִּים אֶת הַמַּצָּה – כְּמוֹ שֶׁמְּכַסִּים אֶת הַחַלּוֹת בְּקִדּוּשׁ שֶׁל שַׁבָּת.","פֶּרֶק ט״ז, הֲלָכָה י״ט","וְהִגַּדְתָּ לְבִנְךָ"],["בְּ״פֶסַח זֶה״ אֵין מַגְבִּיהִים אֶת הַזְּרוֹעַ. מַדּוּעַ?",["כִּי הַזְּרוֹעַ שַׁמְנִית, וְהִיא עֲלוּלָה לְלַכְלֵךְ אֶת הַיָּדַיִם","כִּי הִיא רַק זֵכֶר, וְשֶׁלֹּא נֵרָאֶה כְּמַקְרִיבִים","כִּי אֶת הַזְּרוֹעַ אוֹכְלִים מִיָּד, בִּתְחִלַּת הַסְּעוּדָה","כִּי מַגְבִּיהִים רַק דְּבָרִים שֶׁמְּבָרְכִים עֲלֵיהֶם ״הַמּוֹצִיא״"],1,"הַזְּרוֹעַ אֵינָהּ בְּשַׂר קָרְבַּן פֶּסַח אֶלָּא זֵכֶר בִּלְבַד, וְאִם יַגְבִּיהוּ אוֹתָהּ – זֶה יֵרָאֶה כְּמַקְרִיבִים קָדָשִׁים בַּחוּץ. אֶת הַמַּצָּה וְאֶת הַמָּרוֹר מַגְבִּיהִים.","פֶּרֶק ט״ז, הֲלָכָה י״ט","וְהִגַּדְתָּ לְבִנְךָ"],["אַבָּא וְהַבָּנִים חָזְרוּ מֵהַתְּפִלָּה, וְהַשֻּׁלְחָן עָרוּךְ. מָתַי מְקַדְּשִׁים?",["מִיָּד, גַּם אִם הַשֶּׁמֶשׁ עוֹד לֹא שָׁקְעָה","רַק אַחֲרֵי חֲצוֹת, כְּשֶׁכָּל הַיְּלָדִים כְּבָר יְשֵׁנִים","מִיָּד אַחֲרֵי צֵאת הַכּוֹכָבִים, כְּשֶׁהַקְּטַנִּים עֵרִים","אַחֲרֵי הַסְּעוּדָה, כְּדֵי שֶׁכֻּלָּם יִהְיוּ שְׂבֵעִים"],2,"עוֹרְכִים אֶת הַשֻּׁלְחָן מֵרֹאשׁ כְּדֵי לְקַדֵּשׁ מִיָּד, כְּשֶׁהַקְּטַנִּים עֵרִים. אֲבָל לֹא לִפְנֵי צֵאת הַכּוֹכָבִים, כִּי כּוֹס הַקִּדּוּשׁ הִיא הָרִאשׁוֹנָה מֵאַרְבַּע הַכּוֹסוֹת, וְהֵן שַׁיָּכוֹת לַלַּיְלָה.","פֶּרֶק ט״ז, הֲלָכָה ב׳","וְהִגַּדְתָּ לְבִנְךָ"],["כַּמָּה צָרִיךְ אָדָם מְבֻגָּר לִשְׁתּוֹת לְפָחוֹת מִכָּל כּוֹס?",["רֹב רְבִיעִית, שֶׁהוּא מְלֹא לֻגְמָיו, בְּבַת אַחַת","טִפָּה אַחַת בִּלְבַד, כִּי הָעִקָּר הוּא הַבְּרָכָה","רֹב רְבִיעִית, וּמֻתָּר לְחַלֵּק לְאַט לְאֹרֶךְ הַהַגָּדָה","כּוֹס שְׁלֵמָה שֶׁל רְבִיעִית, וְאֶת הַשְּׁאָר מַשְׁאִירִים"],0,"צָרִיךְ לִשְׁתּוֹת לְפָחוֹת רֹב רְבִיעִית שֶׁהוּא כִּ״מְלֹא לֻגְמָיו״, בִּשְׁתִיָּה אַחַת וּבִרְצִיפוּת. וּלְכַתְּחִלָּה טוֹב לִשְׁתּוֹת אֶת כָּל הַכּוֹס.","פֶּרֶק ט״ז, הֲלָכָה ט׳","וְהִגַּדְתָּ לְבִנְךָ"],["לְדָוִד הַיַּיִן גּוֹרֵם כְּאֵב רֹאשׁ. בְּמָה יִשְׁתֶּה אֶת אַרְבַּע הַכּוֹסוֹת?",["בְּמַיִם בִּלְבַד, כִּי הָעִקָּר הוּא הַכּוֹס עַצְמָהּ","בְּמִיץ עֲנָבִים, אוֹ יַיִן מְעֹרָב בְּמִיץ עֲנָבִים","בְּמִיץ תַּפּוּזִים, כִּי כָּל מַשְׁקֶה מְשַׂמֵּחַ","הוּא פָּטוּר לְגַמְרֵי מִכָּל אַרְבַּע הַכּוֹסוֹת"],1,"מִי שֶׁסּוֹבֵל מֵהַיַּיִן רַשַּׁאי לָצֵאת בְּמִיץ עֲנָבִים, אוֹ לְעָרֵב בַּיַּיִן מִיץ עֲנָבִים. רַק מִי שֶׁהַיַּיִן מַפִּיל אוֹתוֹ לְמִשְׁכָּב – פָּטוּר.","פֶּרֶק ט״ז, הֲלָכָה ז׳","וְהִגַּדְתָּ לְבִנְךָ"],["בְּכוֹר שֶׁצָּם בְּעֶרֶב פֶּסַח רָעֵב מְאוֹד אַחֲרֵי הַקִּדּוּשׁ. מָה מֻתָּר לוֹ?",["מְעַט תַּפּוּחֵי אֲדָמָה אוֹ פֵּרוֹת, בְּלִי לְהַרְבּוֹת","לֶאֱכֹל כְּזַיִת מַצָּה שְׁמוּרָה כְּבָר עַכְשָׁו","לֶאֱכֹל כַּמָּה שֶׁרוֹצֶה, כִּי צָם כָּל הַיּוֹם","לֶאֱכֹל בְּאֶמְצַע הַהַגָּדָה, כְּשֶׁיַּרְגִּישׁ שֶׁהוּא חַלָּשׁ"],0,"מִי שֶׁרָעֵב מְאוֹד יָכוֹל לֶאֱכֹל אַחֲרֵי הַקִּדּוּשׁ מְעַט תַּפּוּחֵי אֲדָמָה, בֵּיצָה אוֹ פֵּרוֹת, וְלֹא יַרְבֶּה – כְּדֵי לֶאֱכֹל אֶת הַמַּצָּה בְּתֵאָבוֹן. אַחֲרֵי שֶׁמַּתְחִילִים אֶת הַהַגָּדָה – אָסוּר לְהַפְסִיק בַּאֲכִילָה.","פֶּרֶק ט״ז, הֲלָכָה י״ג","וְהִגַּדְתָּ לְבִנְךָ"],["מִי חַיָּב בְּסִפּוּר יְצִיאַת מִצְרַיִם וּבְאַרְבַּע כּוֹסוֹת בְּלֵיל הַסֵּדֶר?",["רַק הַגְּבָרִים, כִּי נָשִׁים פְּטוּרוֹת מִמִּצְווֹת שֶׁתְּלוּיוֹת בִּזְמַן","רַק מִי שֶׁעוֹרֵךְ אֶת הַסֵּדֶר, וְהַשְּׁאָר שׁוֹמְעִים מִמֶּנּוּ","גַּם נָשִׁים וּבָנוֹת, כְּמוֹ בְּכָל מִצְווֹת הַלַּיְלָה","הַנָּשִׁים רַק בַּסִּפּוּר, אֲבָל לֹא בְּאַרְבַּע הַכּוֹסוֹת"],2,"בְּמִצְוַת הַסִּפּוּר בְּלֵיל הַסֵּדֶר נָשִׁים חַיָּבוֹת, אַף שֶׁמִּזְּכִירַת יְצִיאַת מִצְרַיִם שֶׁבְּכָל יוֹם הֵן פְּטוּרוֹת. וְגַם בְּאַרְבַּע כּוֹסוֹת נָשִׁים מְצֻוּוֹת, כְּמוֹ בְּכָל מִצְווֹת לֵיל הַסֵּדֶר.","פֶּרֶק ט״ו, הֲלָכָה ב׳; פֶּרֶק ט״ז, הֲלָכָה ז׳","וְהִגַּדְתָּ לְבִנְךָ"],["הַיְּלָדִים מַתְחִילִים לְהֵרָדֵם בְּאֶמְצַע הַהַגָּדָה. מָה כְּדַאי לְהַגִּיד לָהֶם?",["אֶת כָּל הַהַגָּדָה מֵהַתְּחִלָּה, בִּמְהִירוּת רַבָּה","״פֶּסַח, מַצָּה וּמָרוֹר״ – הַשְּׁלֹשָׁה שֶׁבִּלְעָדֵיהֶם לֹא יוֹצְאִים","רַק אֶת ״מַה נִּשְׁתַּנָּה״, כִּי זֶה הַחֵלֶק שֶׁל הַיְּלָדִים","אֶת הַבְּרָכָה עַל הַמַּצָּה, וּלְהַשְׁכִּיב אוֹתָם מִיָּד"],1,"רַבָּן גַּמְלִיאֵל אָמַר: מִי שֶׁלֹּא אָמַר שְׁלֹשָׁה דְּבָרִים אֵלּוּ – פֶּסַח, מַצָּה וּמָרוֹר – לֹא יָצָא. הוֹרִים שֶׁרוֹאִים שֶׁהַיְּלָדִים נִרְדָּמִים אוֹמְרִים לָהֶם קֹדֶם אֶת טַעֲמֵי שְׁלֹשֶׁת הַדְּבָרִים.","פֶּרֶק ט״ו, הֲלָכָה ט׳","וְהִגַּדְתָּ לְבִנְךָ"],["אַבָּא שֶׁל יְהוֹנָתָן נִזְכַּר בְּאֶמְצַע הַסֵּדֶר שֶׁשָּׁכַח לְבָרֵךְ ״שֶׁהֶחֱיָנוּ״ בַּקִּדּוּשׁ. מָה יַעֲשֶׂה?",["יְבָרֵךְ עַכְשָׁו, כִּי כָּל זְמַן הֶחָג אֶפְשָׁר לְבָרֵךְ","יַחֲזֹר עַל כָּל הַקִּדּוּשׁ מֵהַתְּחִלָּה, עִם כּוֹס חֲדָשָׁה","יְחַכֶּה לְקִדּוּשׁ שֶׁל מָחָר, וִיבָרֵךְ אָז פַּעֲמַיִם","הִפְסִיד אֶת הַבְּרָכָה, כִּי ״שֶׁהֶחֱיָנוּ״ רַק בַּקִּדּוּשׁ"],0,"״שֶׁהֶחֱיָנוּ״ הִיא בְּרָכָה עַל הֶחָג, שֶׁמִּתְחַדֵּשׁ מִזְּמַן לִזְמַן. מִי שֶׁשָּׁכַח לְבָרֵךְ בַּקִּדּוּשׁ – מְבָרֵךְ כְּשֶׁנִּזְכָּר, כָּל עוֹד לֹא נִגְמַר חַג הַפֶּסַח.","פֶּרֶק ט״ז, הֲלָכָה ה׳","וְהִגַּדְתָּ לְבִנְךָ"],["רְאוּבֵן שָׁתָה אֶת אַרְבַּע הַכּוֹסוֹת זוֹ אַחַר זוֹ, בְּלִי לוֹמַר בֵּינֵיהֶן אֶת הַהַגָּדָה. מָה הַדִּין?",["יָצָא, כִּי הָעִקָּר הוּא לִשְׁתּוֹת אַרְבַּע כּוֹסוֹת בַּלַּיְלָה","נֶחְשָׁב כְּאִלּוּ שָׁתָה כּוֹס אַחַת בִּלְבַד","יָצָא, וְאַף הִדֵּר, כִּי שָׁתָה בִּזְרִיזוּת רַבָּה","יָצָא רַק בִּשְׁתֵּי כּוֹסוֹת, הָרִאשׁוֹנָה וְהָאַחֲרוֹנָה"],1,"כָּל חֵלֶק בַּהַגָּדָה נֶאֱמָר עַל כּוֹס: הַקִּדּוּשׁ, הַסִּפּוּר וַחֲצִי הַהַלֵּל, בִּרְכַּת הַמָּזוֹן, וְסוֹף הַהַלֵּל. מִי שֶׁשָּׁתָה אֶת אַרְבַּע הַכּוֹסוֹת בִּרְצִיפוּת – כְּאִלּוּ שָׁתָה כּוֹס אַחַת.","פֶּרֶק ט״ז, הֲלָכָה ו׳","וְהִגַּדְתָּ לְבִנְךָ"],["לָמָּה בְּ״וּרְחַץ״, לִפְנֵי הַכַּרְפַּס, נוֹטְלִים יָדַיִם בְּלִי בְּרָכָה?",["כִּי יֵשׁ סוֹבְרִים שֶׁהַיּוֹם לֹא צָרִיךְ נְטִילָה לְדָבָר טָבוּל","כִּי כְּבָר בֵּרַכְנוּ עַל נְטִילַת יָדַיִם לִפְנֵי הַקִּדּוּשׁ","כִּי נְטִילָה זוֹ הִיא רַק בִּשְׁבִיל הַיְּלָדִים, לְעוֹרֵר שְׁאֵלָה","כִּי בְּלֵיל הַסֵּדֶר אֵין מְבָרְכִים עַל שׁוּם נְטִילָה"],0,"לְדַעַת רֹב הָרִאשׁוֹנִים צָרִיךְ לִטֹּל יָדַיִם לִפְנֵי אֲכִילַת דָּבָר שֶׁטָּבוּל בְּמַשְׁקֶה, וּלְבָרֵךְ. אֲבָל יֵשׁ סוֹבְרִים שֶׁהַיּוֹם אֵין צֹרֶךְ בִּנְטִילָה כָּזוֹ. לָכֵן נוֹטְלִים – וְלֹא מְבָרְכִים, כִּי בְּסָפֵק בְּרָכוֹת לֹא מְבָרְכִים.","פֶּרֶק ט״ז, הֲלָכָה י״ד","וְהִגַּדְתָּ לְבִנְךָ"],["הַסֵּדֶר הִתְאָרֵךְ, וְהַשָּׁעָה עָבְרָה אֶת חֲצוֹת לִפְנֵי שֶׁאָכְלוּ מַצָּה. מָה עוֹשִׂים?",["אוֹכְלִים מַצָּה וּמָרוֹר, אֲבָל בְּלִי לְבָרֵךְ עֲלֵיהֶם","כְּבָר אֵין טַעַם לֶאֱכֹל, כִּי הַזְּמַן עָבַר","אוֹכְלִים וּמְבָרְכִים כָּרָגִיל, כִּי זֶה עוֹד לַיְלָה","אוֹכְלִים רַק אֶת הָאֲפִיקוֹמָן, וּמְדַלְּגִים עַל הַשְּׁאָר"],0,"לְדַעַת רַבִּי עֲקִיבָא אֶפְשָׁר לֶאֱכֹל כָּל הַלַּיְלָה, וְלָכֵן אוֹכְלִים. אֲבָל לְדַעַת רַבִּי אֶלְעָזָר בֶּן עֲזַרְיָה הַזְּמַן עָבַר – וְלָכֵן לֹא מְבָרְכִים, שֶׁלֹּא תִּהְיֶה בְּרָכָה לְבַטָּלָה.","פֶּרֶק ט״ז, הֲלָכָה ל״א","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["יוֹסֵף אָכַל אֶת הַכְּזַיִת מַצָּה וְשָׁכַח לְהָסֵב. מָה יַעֲשֶׂה?",["לֹא כְּלוּם, כִּי הוּא כְּבָר אָכַל וּבֵרַךְ","יֹאכַל שׁוּב כְּזַיִת בַּהֲסִבָּה, בְּלִי לְבָרֵךְ שׁוּב","יֹאכַל שׁוּב כְּזַיִת בַּהֲסִבָּה, וִיבָרֵךְ שׁוּב עַל הַמַּצָּה","יָסֵב כְּשֶׁיֹּאכַל אֶת הַמָּרוֹר, וְזֶה יַשְׁלִים"],1,"מִי שֶׁאָכַל מַצָּה בְּלִי הֲסִבָּה לֹא יָצָא, וְחוֹזֵר לֶאֱכֹל בַּהֲסִבָּה. אֲבָל לֹא מְבָרֵךְ שׁוּב, כִּי יֵשׁ רִאשׁוֹנִים שֶׁסּוֹבְרִים שֶׁהַיּוֹם אֵין חוֹבַת הֲסִבָּה. בַּמָּרוֹר לֹא מְסִבִּים בִּכְלָל.","פֶּרֶק ט״ז, הֲלָכָה י״ב","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["אַבְרָהָם שָׁתָה אֶת הַכּוֹס הָרִאשׁוֹנָה בְּלִי הֲסִבָּה. מַה הַדִּין?",["לְכֻלָּם חוֹזֵר וְשׁוֹתֶה, כִּי בְּלִי הֲסִבָּה לֹא יָצָא","לַשֻּׁלְחָן עָרוּךְ חוֹזֵר, וְלָרַמָּ״א אֵינוֹ חוֹזֵר","לְכֻלָּם לֹא חוֹזֵר, כִּי בְּכוֹס אֵין צֹרֶךְ לְהָסֵב","לָרַמָּ״א חוֹזֵר, וְלַשֻּׁלְחָן עָרוּךְ לֹא חוֹזֵר בִּכְלָל"],1,"לְפִי הַשֻּׁלְחָן עָרוּךְ (מִנְהַג הַסְּפָרַדִּים) לְכַתְּחִלָּה חוֹזֵר וְשׁוֹתֶה בַּהֲסִבָּה. לְפִי הָרַמָּ״א (מִנְהַג הָאַשְׁכְּנַזִּים) חוֹזְרִים רַק בַּכּוֹס הַשְּׁנִיָּה, וּבִשְׁאָר הַכּוֹסוֹת לֹא – שֶׁלֹּא יֵרָאֶה כְּמוֹסִיף עַל הַכּוֹסוֹת. וּמִי שֶׁקָּשֶׁה לוֹ – לֹא חוֹזֵר.","פֶּרֶק ט״ז, הֲלָכָה י״ב","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["לְסָבָא אֵין שִׁנַּיִם, וְקָשֶׁה לוֹ לִלְעֹס מַצָּה. אֵיךְ יְקַיֵּם אֶת הַמִּצְוָה?",["יְבַשֵּׁל אֶת הַמַּצָּה בְּמָרָק עַד שֶׁתִּתְרַכֵּךְ","יְפוֹרֵר אוֹתָהּ, אוֹ יַשְׁרֶה אוֹתָהּ מְעַט בְּמַיִם","יֹאכַל עוּגָה מִקֶּמַח מַצָּה בִּמְקוֹם מַצָּה","יַשְׁרֶה אֶת הַמַּצָּה כָּל הַלַּיְלָה, עַד שֶׁתִּמּוֹחַ"],1,"מִי שֶׁקָּשֶׁה לוֹ לִלְעֹס יָכוֹל לְפוֹרֵר אֶת הַמַּצָּה, וְאִם צָרִיךְ – לְהַשְׁרוֹתָהּ בְּמַיִם. אֲבָל מַצָּה מְבֻשֶּׁלֶת, אוֹ שֶׁנִּמּוֹחָה – אִבְּדָה אֶת טַעַם הַמַּצָּה, וְאֵין יוֹצְאִים בָּהּ.","פֶּרֶק ט״ז, הֲלָכָה כ״ט","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["לָמָּה לֹא מַתְחִילִים אֶת הַסֵּדֶר בַּכּוֹרֵךְ, אֶלָּא אוֹכְלִים קֹדֶם מַצָּה לְבַד?",["כִּי הַמַּצָּה מִן הַתּוֹרָה, וְהַמָּרוֹר עָלוּל לִפְגֹּעַ בָּהּ","כִּי הַמַּצָּה לְבַד טְעִימָה יוֹתֵר מֵהַכּוֹרֵךְ","כִּי הִלֵּל הַזָּקֵן אָסַר לֶאֱכֹל מַצָּה עִם מָרוֹר","כִּי אֶת הַכּוֹרֵךְ אוֹכְלִים רַק אַחֲרֵי הַסְּעוּדָה"],0,"הַיּוֹם הַמַּצָּה מִצְוָה מִן הַתּוֹרָה, וְהַמָּרוֹר מִדִּבְרֵי חֲכָמִים. אִם נֹאכַל אוֹתָם יַחַד מִיָּד, הַמָּרוֹר ״יִפְגַּע״ בַּמַּצָּה. לָכֵן אוֹכְלִים קֹדֶם מַצָּה, אַחַר כָּךְ מָרוֹר, וּבַסּוֹף כּוֹרְכִים – זֵכֶר לְהִלֵּל.","פֶּרֶק ט״ז, הֲלָכָה כ״ח","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["מִשְׁפָּחָה שֶׁנּוֹהֶגֶת לֹא לֶאֱכֹל צָלִי בְּלֵיל הַסֵּדֶר. מַה מֻּתָּר לָהֶם לֶאֱכֹל?",["עוֹף צָלוּי בַּתַּנּוּר, כִּי עוֹף אֵינוֹ כָּשֵׁר לַפֶּסַח","דָּג צָלוּי, כִּי דָּגִים אֵינָם צְרִיכִים שְׁחִיטָה","בָּשָׂר שֶׁבִּשְּׁלוּ קֹדֶם, וְאַחַר כָּךְ צָלוּ עַל הָאֵשׁ","בָּשָׂר שֶׁצָּלוּ בְּתוֹךְ סִיר סָגוּר עַל הָאֵשׁ"],1,"אִסּוּר הַצָּלִי חָל עַל כָּל בָּשָׂר, גַּם עוֹף וְגַם צְלִי קְדֵרָה – כִּי הוּא נִרְאֶה צָלוּי. אֲבָל דָּגִים וּבֵיצִים, שֶׁאֵינָם צְרִיכִים שְׁחִיטָה, מֻתָּר לִצְלוֹת.","פֶּרֶק ט״ז, הֲלָכָה ל״ב","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["הַסֵּדֶר נִגְמַר, וְאַבָּא רוֹצֶה לְהַמְשִׁיךְ לִלְמֹד עִם הַבָּנִים. מַה מֻּתָּר לוֹ לִשְׁתּוֹת?",["עוֹד כּוֹס יַיִן, כִּי הַסֵּדֶר כְּבָר הִסְתַּיֵּם","קָפֶה, כְּדֵי שֶׁיּוּכַל לְהַמְשִׁיךְ לַעֲסֹק בַּסִּפּוּר","שׁוּם דָּבָר, אֲפִלּוּ לֹא מַיִם, עַד הַבֹּקֶר","רַק יַיִן לָבָן, כִּי הוּא פָּחוֹת מְשַׁכֵּר"],1,"יַיִן אָסוּר אַחֲרֵי הַסֵּדֶר, כְּדֵי שֶׁיּוּכְלוּ לְהַמְשִׁיךְ לְסַפֵּר וְלִלְמֹד. קָפֶה אוֹ מִיץ – רֹב הַפּוֹסְקִים מַתִּירִים, וּמִי שֶׁשּׁוֹתֶה קָפֶה כְּדֵי לְהַמְשִׁיךְ לִלְמֹד – יִשְׁתֶּה. מַיִם מֻתָּרִים לְכֻלָּם.","פֶּרֶק ט״ז, הֲלָכָה ל״ז","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["לְפִי חֶשְׁבּוֹן הַנֶּפַח, כַּמָּה מַצָּה אוֹכְלִים מִיָּד אַחֲרֵי ״הַמּוֹצִיא״ וְ״עַל אֲכִילַת מַצָּה״?",["פֵּרוּר קָטָן, כִּי הָעִקָּר הוּא הַבְּרָכָה","חֲצִי כְּזַיִת, וְאֶת הַשְּׁאָר מַשְׁלִימִים בַּכּוֹרֵךְ","שְׁנֵי זֵיתִים, כִּשְׁנֵי שְׁלִישׁ מַצָּה","רַק אַחֲרֵי הַסְּעוּדָה, כְּשֶׁאוֹכְלִים אֲפִיקוֹמָן"],2,"כְּזַיִת הוּא כִּשְׁלִישׁ מַצַּת מְכוֹנָה, וּבַהַתְחָלָה אוֹכְלִים שְׁנֵי זֵיתִים – אֶחָד לְ״הַמּוֹצִיא״ וְאֶחָד לְ״עַל אֲכִילַת מַצָּה״. רַבִּים מֵהַסְּפָרַדִּים מוֹדְדִים בְּמִשְׁקָל, וְאוֹכְלִים שְׁתֵּי מַצּוֹת שְׁלֵמוֹת.","פֶּרֶק ט״ז, הֲלָכוֹת כ״ב–כ״ד","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["מָה מְיֻחָד בַּהַלֵּל שֶׁל לֵיל הַסֵּדֶר?",["אוֹמְרִים אוֹתוֹ כְּשִׁירָה, חֶצְיוֹ לִפְנֵי הַסְּעוּדָה וְחֶצְיוֹ אַחֲרֶיהָ","אוֹמְרִים אוֹתוֹ בַּעֲמִידָה, וּמְבָרְכִים עָלָיו פַּעֲמַיִם","אוֹמְרִים אוֹתוֹ רַק בְּבֵית הַכְּנֶסֶת, וְלֹא בַּבַּיִת","אוֹמְרִים אוֹתוֹ בְּלַחַשׁ, כְּדֵי שֶׁהַיְּלָדִים יֵרָדְמוּ"],0,"בְּלֵיל הַסֵּדֶר אוֹמְרִים אֶת הַהַלֵּל כְּשִׁירָה עַל הַגְּאֻלָּה, חֶצְיוֹ לִפְנֵי הַסְּעוּדָה וְחֶצְיוֹ אַחֲרֶיהָ. אוֹמְרִים אוֹתוֹ בִּישִׁיבָה, דֶּרֶךְ חֵרוּת, בְּקוֹל רָם, וְהַמִּנְהָג שֶׁלֹּא לְבָרֵךְ עָלָיו.","פֶּרֶק ט״ז, הֲלָכוֹת כ׳, ל״ה","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["רָחֵל נוֹהֶגֶת לְהָסֵב. הִיא אָכְלָה אֶת הַכְּזַיִת מַצָּה, וְשָׁכְחָה לְהָסֵב. מָה הַדִּין?",["חַיֶּבֶת לַחֲזֹר וְלֶאֱכֹל כְּזַיִת מַצָּה שׁוּב","אֵינָהּ צְרִיכָה לַחֲזֹר וְלֶאֱכֹל שׁוּב","נָשִׁים בִּכְלָל אֵינָן חַיָּבוֹת בַּאֲכִילַת מַצָּה","תַּחֲזֹר וְתֹאכַל, וּתְבָרֵךְ שׁוּב ״עַל אֲכִילַת מַצָּה״"],1,"נָשִׁים חַיָּבוֹת בַּמַּצָּה וּבְאַרְבַּע הַכּוֹסוֹת. אִשָּׁה שֶׁמְּסִבָּה וְשָׁכְחָה – אֵינָהּ צְרִיכָה לַחֲזֹר, וְהָרַב מֶלָמֵד מוֹסִיף שֶׁנָּשִׁים נִכְבָּדוֹת שֶׁשָּׁכְחוּ לְהָסֵב בַּמַּצָּה – טוֹב שֶׁיַּחְזְרוּ. וְרַבּוֹת מִנְּשׁוֹת אַשְׁכְּנַז, לְפִי הָרַמָּ״א, אֵינָן מְסִבּוֹת כְּלָל.","פֶּרֶק ט״ז, הֲלָכָה י״ב","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["שְׁמוּאֵל אוֹכֵל אֶת הַמַּצָּה לְאַט, וּמְפַחֵד שֶׁלֹּא סִיֵּם בַּזְּמַן. מָה נָכוֹן?",["יַעֲמִיד שָׁעוֹן וִימַהֵר, כִּי יֵשׁ לוֹ רַק דַּקָּה אַחַת","אִם אָכַל בִּרְצִיפוּת, בְּלִי הַפְסָקוֹת – וַדַּאי יָצָא","יֹאכַל עוֹד מַצָּה שְׁלֵמָה, כִּי לְאַט לֹא יוֹצְאִים","יִשְׁאַל רַב, כִּי רַק רַב יָכוֹל לִמְדֹּד לוֹ"],1,"אֶת הַכְּזַיִת צָרִיךְ לֶאֱכֹל בְּתוֹךְ ״כְּדֵי אֲכִילַת פְּרָס״ – כַּמָּה דַּקּוֹת. אֲבָל לֹא צָרִיךְ לְהִסְתַּכֵּל בַּשָּׁעוֹן: מִי שֶׁאוֹכֵל בְּנַחַת בְּלִי לְהַפְסִיק בִּדְבָרִים אֲחֵרִים – וַדַּאי יָצָא, גַּם אִם הוּא אוֹכֵל לְאַט.","פֶּרֶק ט״ז, הֲלָכָה כ״ה","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["אֶלְיָקִים אָכַל אֶת הָאֲפִיקוֹמָן וְשָׁכַח לְהָסֵב. הוּא כְּבָר שָׂבֵעַ מְאוֹד. מָה הַדִּין?",["חַיָּב לֶאֱכֹל שׁוּב אֲפִיקוֹמָן שָׁלֵם, גַּם אִם קָשֶׁה לוֹ","אֵינוֹ צָרִיךְ לַחֲזֹר, כִּי הָאֲפִיקוֹמָן זֵכֶר לְקָרְבַּן פֶּסַח","יַחֲזֹר וְיֹאכַל, וְגַם יְבָרֵךְ שׁוּב ״עַל אֲכִילַת מַצָּה״","לֹא יָצָא יְדֵי חוֹבַת מַצָּה כְּלָל בְּכָל הַלַּיְלָה"],1,"לְכַתְּחִלָּה מִי שֶׁשָּׁכַח לְהָסֵב חוֹזֵר וְאוֹכֵל בַּהֲסִבָּה. אֲבָל מִי שֶׁשָּׂבֵעַ וְקָשֶׁה לוֹ – סוֹמֵךְ עַל הַטַּעַם הָעִקָּרִי, שֶׁהָאֲפִיקוֹמָן זֵכֶר לְקָרְבַּן פֶּסַח, וְאֵינוֹ צָרִיךְ לַחֲזֹר.","פֶּרֶק ט״ז, הֲלָכָה ל״ד","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"],["לִפְנֵי הַשֵּׁנָה בְּלֵיל הַסֵּדֶר, מָה אוֹמְרִים מִקְּרִיאַת שְׁמַע שֶׁעַל הַמִּטָּה?",["אֶת כָּל הַפְּסוּקִים וְהַתְּפִלּוֹת, כְּמוֹ בְּכָל לַיְלָה אַחֵר","רַק קְרִיאַת שְׁמַע וּבִרְכַּת ״הַמַּפִּיל״, כִּי זֶה לֵיל שִׁמּוּרִים","שׁוּם דָּבָר, כִּי כְּבָר אָמַרְנוּ הַלֵּל בְּסוֹף הַסֵּדֶר","רַק ״שִׁיר הַשִּׁירִים״, בִּמְקוֹם קְרִיאַת שְׁמַע שֶׁל כָּל לַיְלָה"],1,"בְּכָל הַלֵּילוֹת אוֹמְרִים פְּסוּקִים נוֹסָפִים לִשְׁמִירָה מִן הַמַּזִּיקִים. בְּלֵיל פֶּסַח אוֹמְרִים רַק קְרִיאַת שְׁמַע וּבִרְכַּת ״הַמַּפִּיל״, כִּי הַלַּיְלָה הַזֶּה מְשֻׁמָּר מִן הַמַּזִּיקִים וּמְזֻמָּן לַגְּאֻלָּה.","פֶּרֶק ט״ז, הֲלָכָה ל״ח","מִמַּצָּה וּמָרוֹר עַד נִרְצָה"]]};